/* Imported practice questions. Keep this file out of the public repository (it is listed in .gitignore). */
window.PRIVATE_CASES = {
 "fabrikam": {
  "title": "Case study: Fabrikam Inc.",
  "html": "<p>Fabrikam provides AI-driven demand forecasting and product recommendations to online retailers, and is moving the whole platform to Azure. Developers use Python and the Azure SDKs.</p><ul><li>The customer-facing Recommendation API is a containerized Python app on Azure Container Apps. Front-end and API workloads also run on ACA; batch model retraining runs on AKS.</li><li>Embeddings are stored in Azure Database for PostgreSQL with pgvector. Retrieval combines metadata filtering with vector similarity search. Azure Managed Redis is the cache.</li><li>Images live in ACR and are built by ACR Tasks on commit. AKS workloads are deployed from Kubernetes manifests in Git.</li><li>Logs go to Azure Monitor; teams use container logs, Kubernetes events and KQL.</li></ul><p><b>Requirements:</b> semantic search under 200 ms at peak; vector calculations only on rows that meet the mandatory metadata filters; enough compute and memory to keep vector indexes in RAM; high-concurrency, low-latency database connections; secondary indexes applied only after bulk loads; Redis entries expire after 10 minutes and are invalidated when metadata changes; managed identities for all service and database authentication, no plain-text credentials; secrets stored centrally and rotated automatically; KEDA scaling, with the API scaling on HTTP traffic and batch jobs scaling on queue length down to zero, without runaway costs; images stored in ACR and built by ACR Tasks on commit.</p>"
 },
 "proseware": {
  "title": "Case study: Proseware Inc.",
  "html": "<p>Proseware builds AI-powered knowledge management for enterprises, with semantic search, document retrieval and real-time partner integrations. Developers use Python and the Azure SDKs.</p><ul><li>Microservices are Docker containers. Code is developed locally and stored in GitHub. Custom images are in ACR; base images are on Docker Hub, and custom images must rebuild when a base image updates.</li><li>Azure Cosmos DB for NoSQL stores documents, metadata and vector embeddings. Azure Functions generate embeddings for Cosmos DB documents and send Service Bus messages to trigger index updates.</li><li>ACA apps host the semantic search APIs and process the Service Bus messages. AKS regenerates embeddings in batch when the embedding model changes.</li><li>A partner-facing containerized webhook lets partners submit documents.</li><li>Telemetry goes to Azure Monitor and one Log Analytics workspace (ACA, AKS and Functions logs). Functions currently use the Application Insights SDK.</li></ul><p><b>Requirements:</b> embeddings generated automatically for new or updated documents; APIs scale during business hours with minimal cold start; telemetry correlated across Functions, using OpenTelemetry; minimal development effort; images built and validated inside ACR before merging to main, with no dependency on developer machines or external build services; ACA scales on pending Service Bus messages; Cosmos DB RU use minimized, and vector search uses Cosmos DB embeddings; the partner webhook runs on App Service, which must supply secrets at runtime without relying on external services; secrets never in images, source control or app configuration, stored in Key Vault and read through a managed identity; everything deployed with Bicep through an automated, version-controlled pipeline.</p><p><b>Known issue:</b> RU consumption spikes during vector similarity queries.</p>"
 }
};
window.PRIVATE_QUESTIONS = [
{"id": "eh-1", "topic": "acr", "src": "imported", "num": 1, "q": "You maintain multiple versions of a container image in Azure Container Registry. The production deployment must always run the exact same image build even if tags are changed later. You need to ensure predictable and immutable image selection during deployment. What should you do?", "o": ["Tag the image as production and deploy it by using the production tag.", "Schedule nightly rebuilds of the image.", "Configure deployment to use the latest tag.", "Identify the image by using its SHA digest."], "e": "A digest (sha256) identifies the exact image content and never moves. Tags such as production or latest can be re-pointed to a different build at any time.", "a": 3},
{"id": "eh-2", "topic": "aks", "src": "imported", "num": 2, "q": "A container in an AKS cluster repeatedly restarts. Pod events show probe failures, although node-level CPU and memory metrics are normal. You need to diagnose the cause of the repeating restarts. What should you do first?", "o": ["Scale the deployment to more replicas.", "Decrease the initialDelaySeconds for the container liveness probe.", "Drain and reboot the node hosting the pod.", "Inspect the pod events and container logs."], "e": "Gather evidence before changing anything. Pod events show which probe failed and when, and container logs show what the app was doing. Scaling, changing probe timing or rebooting nodes are guesses.", "a": 3},
{"id": "eh-3", "topic": "aca", "src": "imported", "num": 3, "q": "You develop a message-processing service deployed to Azure Container Apps. The service reads messages from an Azure Service Bus queue. The solution must minimize costs by ensuring NO compute resources are consumed when the queue is empty. You need to configure scaling for the service. Which two actions should you perform?", "type": "multi", "o": ["Increase the scaling rule to allow for the maximum running replica count.", "Configure the scaling rule to allow for the termination of all active replicas.", "Configure a Kubernetes Event-driven Autoscaler rule that monitors queue length.", "Enable HTTP ingress concurrency scaling."], "c": [1, 2], "e": "A KEDA rule on queue length scales on waiting messages, and allowing all replicas to terminate (minimum replicas 0) means nothing runs while the queue is empty. HTTP scaling doesn't apply to a queue consumer."},
{"id": "eh-4", "topic": "acr", "src": "imported", "num": 4, "q": "You configure ACR Tasks to automate image builds. Container images must rebuild when: Application updates occur. Base image updates occur, such as when the underlying OS image is updated. Regular scheduled rebuilds are required. You need to configure ACR Tasks to support automated image rebuilds. Which three triggers should you configure?", "type": "multi", "o": ["Timer trigger", "Source code commit trigger", "Registry event trigger", "Base image update trigger", "Webhook notification trigger"], "c": [0, 1, 3], "e": "Each requirement maps to a native ACR Tasks trigger: a timer for the schedule, a source code commit trigger for app changes, and a base image update trigger for OS or runtime patches."},
{"id": "eh-5", "topic": "aca", "src": "imported", "num": 5, "type": "order", "q": "You are developing several microservices to run on Azure Container Apps. The microservices must allow HTTPS access by using a custom domain. You need to configure the custom domain in Azure Container Apps. In which order should you perform the actions?", "items": ["Enable ingress.", "Add DNS records to the domain provider.", "Validate the custom domain name.", "Add the custom domain name.", "Bind the certificate."], "e": "Ingress gives you the endpoint the DNS records point at. Azure then validates ownership through those records, the domain is added, and finally a certificate is bound for HTTPS."},
{"id": "eh-6", "topic": "aca", "src": "imported", "num": 6, "q": "You plan to deploy an Azure Container app. You need to configure the container app to support session affinity. Which ingress type and revision mode should you assign to the container app?", "o": ["TCP ingress type and single revision mode", "TCP ingress type and multiple revision mode", "HTTP ingress type and multiple revision mode", "HTTP ingress type and single revision mode"], "e": "Session affinity (sticky sessions) works with HTTP ingress and is supported only in single revision mode.", "a": 3},
{"id": "eh-7", "topic": "aca", "src": "imported", "num": 7, "type": "match", "q": "You deploy an API to Azure Container Apps. The solution must provide the following functionality: <br>• Support the concurrent activation of multiple application versions. <br>• Allocate a specific percentage of incoming requests to a secondary version. You need to configure revision behavior. Which configurations should you use?", "pairs": [["Test a new revision without affecting production traffic.", "Multiple revision mode"], ["Route 20 percent of traffic to a new revision.", "Traffic splitting"]], "extra": ["Single revision mode", "Traffic isolation"], "e": "Multiple revision mode keeps several revisions active, and a new revision gets no production traffic until you give it some. Traffic splitting assigns a percentage of requests to each revision."},
{"id": "eh-8", "topic": "acr", "src": "imported", "num": 8, "type": "order", "q": "You plan to create a Docker image that runs an ASP.NET Core application named ContosoApp. You have a setup script named setupScript.ps1 and a series of application files including ContosoApp.dll. You need to create a Dockerfile document that meets the following requirements: <br>• Call setupScript.ps1 when the container is built. <br>• Run ContosoApp.dll when the container starts. The Dockerfile document must be created in the same folder where ContosoApp.dll and setupScript.ps1 are stored. Which five commands should you use to develop the solution?", "items": ["FROM microsoft/aspnetcore:latest", "WORKDIR /apps/ContosoApp", "COPY ./ .", "RUN powershell ./setupScript.ps1", "CMD [\"dotnet\", \"ContosoApp.dll\"]"], "e": "FROM sets the base image, WORKDIR sets the folder, COPY brings in the app files, RUN executes the setup script at build time, and CMD runs the app when the container starts."},
{"id": "eh-9", "topic": "acr", "src": "imported", "num": 9, "type": "match", "q": "You are preparing a container image for deployment to production. The container image build and deployment process must ensure the following: <br>• The image is uniquely versioned. <br>• Secure authentication is used when pushing the image to Azure Container Registry (ACR). <br>• The image is stored in ACR for deployment. You need to ensure that the container image build-and-push process meets the requirements. Which action should you perform for each requirement?", "pairs": [["Ensure that the image is versioned.", "Use a unique tag for the image."], ["Allow secure push to ACR.", "Authenticate to ACR by using Microsoft Entra ID."], ["Store the image in the registry for deployment.", "Push the image to ACR."]], "extra": ["Build the image locally."], "e": "A unique tag (such as a version or build ID) versions the image, Entra ID authentication secures the push, and pushing stores the image in ACR."},
{"id": "eh-10", "topic": "aks", "src": "imported", "num": 10, "type": "match", "q": "You plan to deploy a web application to AKS. The solution must: <br>• Scale out the application by adding more pods during peak CPU usage. <br>• Expose the application internally within the cluster only. You need to configure a Kubernetes resource for each requirement. Which resources should you configure?", "pairs": [["Scale out the application.", "HorizontalPodAutoscaler"], ["Expose the application internally only.", "ClusterIP service"]], "extra": ["Ingress", "Deployment", "VerticalPodAutoscaler"], "e": "The HPA adds pod replicas based on CPU or other metrics; the VPA resizes pods instead. A ClusterIP service gets an internal IP that is reachable only from inside the cluster."},
{"id": "eh-11", "topic": "aca", "src": "imported", "num": 11, "q": "You deploy a new revision of an app in ACA. You need to gradually shift production traffic to the revision while monitoring performance. In addition, you need to be able to quickly roll back. Which two actions should you perform?", "type": "multi", "o": ["Use single revision mode.", "Restart the revision.", "Enable multiple revision mode.", "Increase replica count.", "Use traffic splitting."], "c": [2, 4], "e": "Multiple revision mode keeps old and new revisions active together, and traffic splitting sets the share each one gets. Rolling back is just moving the weight back."},
{"id": "eh-12", "topic": "sec", "src": "imported", "num": 12, "type": "select", "q": "You plan to deploy an Azure Container Apps app named App1. App1 will use an access key to connect to a backend API. The solution must store the key outside of the App1 environment and minimize maintenance efforts. You need to configure secure key storage for App1. Which configurations should you use?", "slots": [{"l": "Provide the key storage for App1.", "c": ["Azure Key Vault key", "Azure Key Vault secret", "Azure Container Apps secret"], "a": "Azure Key Vault secret"}, {"l": "Secure App1 access to the key storage.", "c": ["Service principal", "Managed identity", "Workload identity"], "a": "Managed identity"}], "e": "An access key is a secret, so it belongs in a Key Vault secret (Key Vault keys are cryptographic keys). A managed identity lets App1 read it with no credentials to manage."},
{"id": "eh-13", "topic": "acr", "src": "imported", "num": 13, "q": "You have container source code stored in a Git repository. The container registry must automatically build and store a new container image whenever a developer commits code to the Git repository. You must minimize the use of an external build infrastructure. You need to configure Azure Container Registry (ACR) to manage the build process natively and automatically. Which two ACR components should you use?", "type": "multi", "o": ["Webhook", "Quick task", "Artifact Cache rule", "Source-triggered task"], "c": [0, 3], "e": "A source-triggered ACR task builds inside Azure on each commit. ACR registers a webhook on the Git repository so it is notified of commits. A quick task is a one-off manual build."},
{"id": "eh-14", "topic": "aks", "src": "imported", "num": 14, "type": "order", "q": "You have an existing AKS cluster and a container image stored in Azure Container Registry. You must deploy a new version without interrupting traffic. You need to perform a rolling update by using a manifest file. Which three actions should you perform in sequence?", "items": ["Update the image tag in the deployment manifest.", "Apply the updated manifest.", "Verify rollout status."], "extra": ["Delete the existing deployment and recreate it.", "Scale deployment to zero before updating."], "e": "Change the image tag, run kubectl apply so Kubernetes replaces pods gradually, then watch kubectl rollout status. Deleting or scaling to zero would cause downtime."},
{"id": "eh-15", "topic": "sec", "src": "imported", "num": 15, "type": "order", "q": "You are deploying an AI service to ACA. The service must retrieve secrets securely from Key Vault by using managed identity. You need to configure secure access. Which three actions should you perform in sequence?", "items": ["Assign a system-assigned managed identity.", "Grant the Key Vault Secrets User role to the managed identity.", "Retrieve the secret by using the SDK."], "extra": ["Configure an access policy with the recover permission."], "e": "The identity has to exist before it can be granted a role, and it needs the role before the app can read secrets with the SDK. Secrets User is the least-privilege read role."},
{"id": "eh-16", "topic": "pg", "src": "imported", "num": 16, "case": "fabrikam", "type": "select", "q": "You need to configure the database resources for the Azure Database for PostgreSQL instance. How should you complete the configuration to meet the business and technical requirements?", "slots": [{"l": "Meet the 200 ms semantic search latency requirement.", "c": ["Increase compute vCores.", "Increase max_connections.", "Increase memory allocation."], "a": "Increase compute vCores."}, {"l": "Optimize the environment for high-dimensional pgvector index residency.", "c": ["Enable read replica.", "Increase max_connections.", "Increase memory allocation."], "a": "Increase memory allocation."}, {"l": "Support the continuous ingestion of transaction-based embeddings.", "c": ["Enable storage autoscale.", "Increase compute vCores.", "Increase backup retention."], "a": "Enable storage autoscale."}], "e": "Distance calculations are CPU-bound, so more vCores cut latency. Vector indexes such as HNSW need to fit in RAM, so add memory. Storage autoscale keeps up with a growing volume of embeddings."},
{"id": "eh-17", "topic": "aks", "src": "imported", "num": 17, "case": "fabrikam", "type": "select", "q": "You need to deploy a batch retraining workload. How should you complete the scaling configuration?", "slots": [{"l": "Trigger scaling based on queue depth.", "c": ["CPU utilization scaler", "Azure Service Bus scaler", "HTTP concurrency scaler"], "a": "Azure Service Bus scaler"}, {"l": "Deallocate instances when the message queue is empty.", "c": ["Minimum replicas = 0", "Minimum replicas = 1"], "a": "Minimum replicas = 0"}, {"l": "Prevent uncontrolled burst scaling.", "c": ["Maximum replicas = 10", "Allow the system to determine the maximum replicas"], "a": "Maximum replicas = 10"}], "e": "The Service Bus scaler reacts to queue length, a minimum of 0 lets the job scale to zero when idle, and a fixed maximum stops runaway scaling costs."},
{"id": "eh-18", "topic": "aca", "src": "imported", "num": 18, "type": "select", "q": "You are developing a microservices-based application that uses Azure Container Apps. The application consists of several containerized services that handle tasks, such as processing orders, managing inventory, and generating reports. You must secure the container apps. All apps must reside in the same virtual network, share the same Dapr configuration, and share the same logging location. Apps must support the configuration of the amount of memory and compute resources available to containers. You need to configure the Azure Container App. How should you complete the CLI command?", "code": "az containerapp [1] [2] -n MyContainerApp -g MyResourceGroup --location eastus2 [3]", "slots": [{"l": "[1]", "c": ["env", "create", "add-on"], "a": "env"}, {"l": "[2]", "c": ["env", "create", "add-on"], "a": "create"}, {"l": "[3]", "c": ["--enable-mtls", "--internal-only", "--enable-workload-profiles"], "a": "--enable-workload-profiles"}], "e": "Apps that share a virtual network, Dapr configuration and log destination live in one Container Apps environment, created with az containerapp env create. Workload profiles let you choose the CPU and memory available to containers."},
{"id": "eh-19", "topic": "func", "src": "imported", "num": 19, "type": "match", "q": "You are designing a solution that will use two Azure Functions apps: App1 and App2. App1 is Windows-based and will be deployed as code. App2 is Linux-based and will be deployed as a container image. Estimates show that the duration of the request processing for both apps will range from 1 to 10 minutes. You plan to implement App1 and App2 by using the hosting plan to satisfy the following requirements: <br>• Request processing can complete within the estimated time range. <br>• The autoscaling behavior is event-driven. <br>• The upper scaling limit is maximized. You need to create the hosting plan for the implementation. Which hosting plan should you create?", "pairs": [["App1 (Windows, deployed as code)", "Premium"], ["App2 (Linux, deployed as a container image)", "Premium"]], "extra": ["Dedicated", "Consumption"], "e": "Premium gives event-driven scaling, runs longer than the 10-minute Consumption limit comfortably, supports Linux container images, and has a higher scale-out limit than Dedicated."},
{"id": "eh-20", "topic": "pg", "src": "imported", "num": 20, "case": "fabrikam", "type": "order", "q": "You need to implement the semantic retrieval workflow for the recommendation engine to meet the technical and performance requirements of Fabrikam Inc. Which four actions should you perform in sequence?", "items": ["Define a table schema with vector and metadata columns.", "Load embedding vectors and associated product metadata.", "Configure a Hierarchical Navigable Small World (HNSW) index on the embedding vector columns.", "Perform a similarity search using a WHERE clause and the &lt;=&gt; operator."], "extra": ["Increase the Redis memory allocation for the caching layer.", "Create a B-tree index on the embedding vector columns."], "e": "Create the table, bulk load the data, then build the HNSW index (indexes go on after bulk loading), and finally query with a metadata WHERE clause and the cosine distance operator. B-tree indexes don't work for vectors."},
{"id": "eh-21", "topic": "pg", "src": "imported", "num": 21, "case": "fabrikam", "q": "You need to optimize vector search queries based on the technical requirements. What should you do?", "o": ["Create a B-tree index on metadata filter columns.", "Increase the max_connections parameter.", "Increase the shared_buffers setting.", "Create an IVFFlat index on the embedding column."], "e": "Vector math must only run on rows that pass the metadata filters. B-tree indexes on the filter columns narrow the candidate rows quickly, so far fewer distance calculations are needed.", "a": 0},
{"id": "eh-22", "topic": "pg", "src": "imported", "num": 22, "case": "fabrikam", "type": "select", "q": "You need to optimize secure database connectivity from the containerized Recommendation API. How should you configure the application?", "slots": [{"l": "Comply with the authentication policy for database access.", "c": ["Use connection pooling library.", "Use managed identity authentication.", "Store credentials in environment variables."], "a": "Use managed identity authentication."}, {"l": "Support high-concurrency requests with minimal latency.", "c": ["Use unlimited pool size.", "Use a connection pooling library.", "Increase the database max_connections parameter."], "a": "Use a connection pooling library."}, {"l": "Protect database stability during traffic spikes.", "c": ["Configure maximum pool size.", "Enable asynchronous query execution.", "Implement a retry policy with exponential backoff."], "a": "Configure maximum pool size."}], "e": "Managed identity meets the no-credentials rule, a pooling library reuses connections for low latency, and a maximum pool size caps how many connections a spike can open."},
{"id": "eh-23", "topic": "pg", "src": "imported", "num": 23, "case": "fabrikam", "q": "You need to improve throughput for concurrent application requests to PostgreSQL. What should you implement?", "o": ["Implement connection pooling.", "Increase shared_buffers.", "Enable read replicas.", "Increase max_connections."], "e": "Opening PostgreSQL connections is expensive. Connection pooling (for example the built-in PgBouncer) reuses a small set of connections, which is what high concurrency with low latency needs.", "a": 0},
{"id": "eh-24", "topic": "redis", "src": "imported", "num": 24, "case": "fabrikam", "type": "match", "q": "You need to configure the Redis integration for the Recommendation API. Which configurations should you use?", "pairs": [["Comply with the defined expiration policy for recommendation results.", "Configure Time to Live on each cache key."], ["Support the data integrity and freshness requirement for catalog updates.", "Publish invalidation events to a Redis channel."], ["Meet the search latency target for recurring product requests.", "Implement cache-aside pattern with lazy loading."]], "extra": ["Enable Redis RDB persistence."], "e": "A TTL enforces the 10-minute expiry, invalidation events remove entries when metadata changes, and cache-aside serves repeat requests from Redis."},
{"id": "eh-25", "topic": "cosmos", "src": "imported", "num": 25, "q": "You deploy multiple instances of a change feed processor to handle a high ingestion rate within Azure Cosmos DB for NoSQL. Each processor instance must process a different subset of partitions. You need to ensure the workload is load-balanced across all processor instances. What should you configure?", "o": ["indexing precision", "strong consistency", "lease container", "autoscale throughput"], "e": "The lease container records which processor instance owns which partition range. Instances use it to split the work and to take over if one stops.", "a": 2},
{"id": "eh-26", "topic": "pg", "src": "imported", "num": 26, "q": "An application performs similarity search across 5 million embeddings stored in Azure Database for PostgreSQL with pgvector. Queries often filter by department before ranking by cosine distance. P95 latency for vector similarity queries exceeds the SLA target. Monitoring shows sustained high CPU use during query execution. You need to reduce P95 latency for filtered vector similarity queries. What should you do?", "o": ["Create B-tree indexes on frequently filtered metadata columns.", "Store embeddings as JSON.", "Increase embedding dimensionality.", "Increase statement timeout."], "e": "Sustained high CPU means too many distance calculations. Indexing the department filter cuts the candidate rows before ranking. JSON storage and more dimensions make it slower, and a longer timeout hides the problem.", "a": 0},
{"id": "eh-27", "topic": "cosmos", "src": "imported", "num": 27, "q": "You store embeddings in a property named embedding in an Azure Cosmos DB for NoSQL container. You must retrieve the five most similar documents to an input embedding. You need to construct the similarity query. What should you do?", "o": ["Use offset pagination.", "Enforce strong consistency.", "Group by embedding value.", "Limit the number of results."], "e": "Order by VectorDistance and return only the top results, for example SELECT TOP 5 ... ORDER BY VectorDistance(c.embedding, @v).", "a": 3},
{"id": "eh-28", "topic": "cosmos", "src": "imported", "num": 28, "q": "You are developing a Java application to be deployed in Azure. The application stores sensitive data in Azure Cosmos DB. You need to configure Always Encrypted to encrypt the sensitive data inside the application. What should you do first?", "o": ["Create a customer-managed key (CMK) and store the key in a new Azure Key Vault instance.", "Create a data encryption key (DEK) by using the Azure Cosmos DB SDK and store the key in Azure Cosmos DB.", "Create a Microsoft Entra ID managed identity and assign the identity to a new Azure Key Vault instance.", "Create a new container to include an encryption policy with the JSON properties to be encrypted."], "e": "Always Encrypted wraps each data encryption key with a customer-managed key in Key Vault, so the CMK has to exist before you can create a DEK or an encryption policy.", "a": 0},
{"id": "eh-29", "topic": "redis", "src": "imported", "num": 29, "q": "You are developing an AI search API that caches semantic search results in Redis. Search results must remain cached for 10 minutes. If the underlying data changes, cached entries must NOT be returned. You need to implement a cache-aside strategy to ensure data consistency. Which two actions should you perform?", "type": "multi", "o": ["Configure a cache notification for key space events.", "Delete related cache keys when the source data changes.", "Implement sliding expiration based on key access.", "Configure a 10-minute Time to Live on each key."], "c": [1, 3], "e": "A fixed 10-minute TTL meets the time limit, and deleting related keys when source data changes stops stale results from being served. Sliding expiration could keep a key alive indefinitely."},
{"id": "eh-30", "topic": "redis", "src": "imported", "num": 30, "q": "You store embeddings in Redis by using keys formatted as doc:(id). Some embeddings are accessed frequently. Others are rarely used. You need to implement a caching strategy that keeps only frequently accessed embeddings in memory. What should you use?", "o": ["volatile-ttl", "allkeys-lru", "EXPIRE command", "time-window expiration"], "e": "allkeys-lru evicts the least recently used keys across the whole keyspace when memory is full, so frequently used embeddings stay. volatile-ttl only considers keys that have a TTL.", "a": 1},
{"id": "eh-31", "topic": "cosmos", "src": "imported", "num": 31, "q": "You deploy an AI application across multiple Azure regions. The application must be able to view writes across all regions within a predictable time window. You need to determine the appropriate consistency level. What are two consistency levels you can use to achieve the goal?", "type": "multi", "o": ["Session", "Strong", "Bounded staleness", "Eventual"], "c": [1, 2], "e": "Strong consistency shows writes immediately everywhere. Bounded staleness guarantees reads lag by no more than a configured time or number of versions. Session and Eventual give no global time guarantee."},
{"id": "eh-32", "topic": "cosmos", "src": "imported", "num": 32, "type": "select", "q": "You are developing an event-driven system that reacts to new or updated documents in Azure Cosmos DB for NoSQL. The application must process new or updated documents as they appear in the container by using a change feed processor. The application must also maintain processor state between runs. You need to configure the components required for stateful change feed processing. Which components should you configure?", "slots": [{"l": "Read changes from the source container.", "c": ["Lease container", "Monitored container", "Vector container"], "a": "Monitored container"}, {"l": "Store continuation state and partition ownership.", "c": ["Indexing container", "Lease container", "Monitored container"], "a": "Lease container"}, {"l": "Process new or updated items in the default change feed mode.", "c": ["Full scan mode", "Latest version mode", "Strong consistency mode"], "a": "Latest version mode"}], "e": "The processor reads from the monitored container, keeps its checkpoints and partition leases in the lease container, and by default uses latest version mode, which returns inserts and updates."},
{"id": "eh-33", "topic": "pg", "src": "imported", "num": 33, "type": "select", "q": "You are developing an application that uses a Python API to perform similarity queries against Azure Database for PostgreSQL. The application creates a new database connection for every request. During peak traffic, the application intermittently fails to open new database sessions. Logs indicate that the maximum number of connections have been reached. You need to configure the connection pooling strategy to reduce connection setup overhead and maximize reuse for the high-concurrency workload. What should you configure?", "slots": [{"l": "Connection pooling technology", "c": ["PgBouncer", "Compute tier scaling", "Automatic vacuum", "Connection timeout extension"], "a": "PgBouncer"}, {"l": "Pooling mode", "c": ["Session pooling mode", "Direct connection mode", "Statement pooling mode", "Transaction pooling mode"], "a": "Transaction pooling mode"}], "e": "PgBouncer is built into Azure Database for PostgreSQL flexible server. Transaction pooling returns a connection to the pool after each transaction, which gives the most reuse under high concurrency."},
{"id": "eh-34", "topic": "redis", "src": "imported", "num": 34, "type": "select", "q": "You are developing a Retrieval-Augmented Generation (RAG) solution for a company. AI responses and embedding vectors are cached in Redis. The solution must meet the following requirements: AI responses must expire exactly 24 hours after they are cached. Cached embeddings must always reflect the current source data. You need to configure Redis to meet the requirements.", "slots": [{"l": "AI responses must expire exactly 24 hours after they are cached.", "c": ["Configure allkeys-lru eviction.", "Reset expiration on every read.", "Set a Time to Live (TTL) on each key."], "a": "Set a Time to Live (TTL) on each key."}, {"l": "Cached embeddings must always reflect the current source data.", "c": ["Configure volatile-lru eviction.", "Delete related keys when the document changes.", "Increase maximum memory allocation."], "a": "Delete related keys when the document changes."}], "e": "A TTL set once (not reset on read) expires the response exactly 24 hours later. Deleting the related keys when a document changes stops stale embeddings from being served."},
{"id": "eh-35", "topic": "redis", "src": "imported", "num": 35, "type": "select", "q": "You are implementing semantic retrieval in Redis. The solution must support low-latency, approximate nearest neighbor (ANN) vector similarity search for large- scale AI retrieval workloads. You need to select the appropriate vector schema settings. Which configuration values should you select?", "slots": [{"l": "Field type for embedding", "c": ["Numeric", "Tag", "Vector"], "a": "Vector"}, {"l": "Index configuration", "c": ["Flat index", "HNSW index", "Metadata index"], "a": "HNSW index"}], "e": "Embeddings go in a VECTOR field. HNSW is the approximate nearest neighbor index; FLAT is exact brute-force search, which is slower at large scale."},
{"id": "eh-36", "topic": "cosmos", "src": "imported", "num": 36, "type": "match", "q": "You are developing a .NET application that uses Azure Cosmos DB for NoSQL to store application data. The application uses the Azure Cosmos DB for NoSQL SDK to interact with the database account. The application must perform the following tasks: Initialize the connection by using the account endpoint and key. Define shared throughput. Perform create, read, update, and delete (CRUD) operations on items stored in a container. You need to implement the SDK components required for the application to access and manage data in Azure Cosmos DB for NoSQL. Which SDK components should you use?", "pairs": [["Initialize the connection by using the account endpoint and key.", "CosmosClient"], ["Define shared throughput.", "Database"], ["Perform item CRUD operations.", "Container"]], "extra": ["Indexing policy"], "e": "CosmosClient connects to the account, shared (database-level) throughput is set on the Database, and items are created, read, updated and deleted through a Container."},
{"id": "eh-37", "topic": "cosmos", "src": "imported", "num": 37, "type": "select", "q": "You are developing a new page for a website that uses Azure Cosmos DB for data storage. The feature uses documents that have the following format: You must display data for the new page in a specific order. You create the following query for the page: You need to configure an Azure Cosmos DB policy to support the query. How should you configure the policy?", "code": "Document:  { \"name\": \"John\", \"city\": \"Seattle\" }\n\nQuery:\nSELECT * FROM People p\nORDER BY p.name, p.city DESC\n\nIndexing policy:\n{\n  \"automatic\": true,\n  \"indexingMode\": \"Consistent\",\n  \"includedPaths\": [ { \"path\": \"/*\" } ],\n  \"excludedPaths\": [ ],\n  \"[1]\": [\n    [\n      { \"path\": \"/name\", \"order\": \"descending\" },\n      { \"path\": \"/city\", \"order\": \"[2]\" }\n    ]\n  ]\n}", "slots": [{"l": "[1]", "c": ["orderBy", "sortOrder", "compositeIndexes"], "a": "compositeIndexes"}, {"l": "[2]", "c": ["ascending", "descending"], "a": "ascending"}], "e": "ORDER BY on two properties needs a composite index. The index must match the query's sort order or its exact reverse: the query is name ascending, city descending, so name descending with city ascending works."},
{"id": "eh-38", "topic": "pg", "src": "imported", "num": 38, "q": "You are designing an Azure Database for PostgreSQL table for semantic search. Queries frequently filter on the created_at column. The schema must support vector similarity search and reliable date filtering. You need to ensure that the table meets the requirements. Which two actions should you perform?", "type": "multi", "o": ["Store created_at as a free-form string.", "Store embeddings in a pg vector column.", "Store embeddings in a varchar column.", "Use a typed timestamp column for created_at."], "c": [1, 3], "e": "The pgvector vector type enables distance operators and vector indexes. A typed timestamp column compares, sorts and indexes dates correctly; strings don't."},
{"id": "eh-39", "topic": "cosmos", "src": "imported", "num": 39, "type": "select", "q": "You have a web service that is used to pay for food deliveries. The web service uses Azure Cosmos DB as the data store. You plan to add a new feature that allows users to set a tip amount. The new feature requires that a property named tip on the document in Azure Cosmos DB must be present and contain a numeric value. There are many existing websites and mobile apps that use the web service that will not be updated to set the tip property for some time. How should you complete the trigger?", "code": "function ensureTip() {\n  var r = [1]\n  var i = r.getBody();\n  [2]\n    i[\"tip\"] = 0;\n  }\n  [3]\n}", "slots": [{"l": "[1]", "c": ["__.value();", "__.readDocument(\"item\");", "getContext().getRequest();", "getContext().getResponse();"], "a": "getContext().getRequest();"}, {"l": "[2]", "c": ["if (!(\"tip\" in i)) {", "if (request.getValue(\"tip\") === null) {", "if (isNaN(i[\"tip\"]) || i[\"tip\"] === null) {", "if (typeof __.pluck(\"tip\") == \"number\") {"], "a": "if (!(\"tip\" in i)) {"}, {"l": "[3]", "c": ["r.setBody(i);", "r.setValue(i);", "__.upsertDocument(i);", "__.replaceDocument(i);"], "a": "r.setBody(i);"}], "e": "This is a pre-trigger: it gets the incoming request, reads the document body, adds tip = 0 when the property is missing, and writes the body back with setBody before the document is saved."},
{"id": "eh-40", "topic": "cosmos", "src": "imported", "num": 40, "type": "order", "q": "You are developing a Python application that reads data from Azure Cosmos DB for NoSQL by using the azure- cosmos SDK. You need to connect to an existing account and run a SQL query against an existing container. Which four actions should you perform in sequence?", "items": ["Initialize CosmosClient.", "Initialize DatabaseProxy.", "Obtain the container reference.", "Run the query."], "extra": ["Specify the database name."], "e": "The SDK hierarchy is client, then database, then container. You run queries on the container proxy, for example with query_items."},
{"id": "eh-41", "topic": "cosmos", "src": "imported", "num": 41, "type": "match", "q": "You are developing a solution for a hospital to support the following use cases: <br>• The most recent patient status details must be retrieved even if multiple users in different locations have updated the patient record. <br>• Patient health monitoring data retrieved must be the current version or the prior version. <br>• After a patient is discharged and all charges have been assessed, the patient billing record contains the final charges. You provision an Azure Cosmos DB for NoSQL database and set the default consistency level for the database account to Strong. You set the value for Indexing Mode to Consistent. You need to minimize latency and any impact to the availability of the solution. You must override the default consistency level at the query level to meet the required consistency guarantees for the scenarios. Which consistency levels should you implement?", "pairs": [["Return the most recent patient status.", "Strong"], ["Return health monitoring data that is no less than one version behind.", "Bounded Staleness"], ["After a patient is discharged and all charges are assessed, retrieve the correct billing data with the final charges.", "Eventual"]], "extra": ["Session", "Consistent Prefix"], "e": "Strong always returns the latest write. Bounded staleness limits how far reads can lag (here, one version). Final billing data no longer changes, so Eventual is enough and has the lowest latency."},
{"id": "eh-42", "topic": "cosmos", "src": "imported", "num": 42, "type": "select", "q": "You develop an application that sells AI generated images based on user input. You recently started a marketing campaign that displays unique ads every second day. Sales data is stored in Azure Cosmos DB with the date of each sale being stored in a property named 'whenFinished'. The marketing department requires a view that shows the number of sales for each unique ad. You need to implement the query for the view. How should you complete the query?", "code": "SELECT [1], [2]\nFROM c\nGROUP BY [3]", "slots": [{"l": "[1]", "c": ["max(c.whenFinished)", "sum(c.whenFinished)", "count(c.whenFinished)"], "a": "count(c.whenFinished)"}, {"l": "[2]", "c": ["DateTimeBin(c.whenFinished, 'day', 2)", "DateTimePart(c.whenFinished, 'day', 2)", "DateTimeBin(c.whenFinished, 'hour', 12)", "DateTimePart(c.whenFinished, 'hour', 12)"], "a": "DateTimeBin(c.whenFinished, 'day', 2)"}, {"l": "[3]", "c": ["DateTimeBin(c.whenFinished, 'day', 2)", "DateTimePart(c.whenFinished, 'day', 2)", "DateTimeBin(c.whenFinished, 'hour', 12)", "DateTimePart(c.whenFinished, 'hour', 12)"], "a": "DateTimeBin(c.whenFinished, 'day', 2)"}], "e": "count() gives the number of sales. DateTimeBin rounds each date down to a two-day bucket, matching an ad that changes every second day. GROUP BY can't use an alias, so the same expression is repeated."},
{"id": "eh-43", "topic": "cosmos", "src": "imported", "num": 43, "type": "match", "q": "You are implementing a Retrieval-Augmented Generation (RAG) system by using the native vector search capabilities of Azure Cosmos DB for NoSQL API. You have a container named Documents that stores technical articles. Each article includes a property named embedding. You must ensure that the system can perform efficient similarity searches between user queries and the stored articles. You need to configure the database resources to support semantic retrieval. Which configurations should you use?", "pairs": [["Facilitate mathematical distance calculations between data points.", "Configure a vector index."], ["Define the document schema for high-dimensional data.", "Store data as a numeric array."]], "extra": ["Configure a composite index.", "Store data as a Base64 encoded string."], "e": "A vector index (with a vector embedding policy) makes distance calculations fast. Embeddings are stored as arrays of numbers so Cosmos DB can compute distances on them."},
{"id": "eh-44", "topic": "pg", "src": "imported", "num": 44, "type": "match", "q": "A semantic search application queries Azure Database for PostgreSQL and stores document embeddings and metadata in a table with the following columns: <br>• embedding (pgvector) <br>• department <br>• created_at The application must return the top five most similar documents for a given query embedding only from the finance department. You need to implement semantic retrieval with metadata filtering. Which query components should you select?", "pairs": [["Filter rows to finance.", "WHERE department = 'Finance'"], ["Rank by similarity and return the top five.", "ORDER BY embedding &lt;=&gt; :query_embedding LIMIT 5"]], "extra": ["WHERE department ILIKE '%fin%'", "ORDER BY created_at DESC LIMIT 5"], "e": "An exact WHERE filter limits rows to the finance department. Ordering by the &lt;=&gt; cosine distance operator and LIMIT 5 returns the five closest matches."},
{"id": "eh-45", "topic": "cosmos", "src": "imported", "num": 45, "q": "You develop an AI application that stores telemetry documents in Azure Cosmos DB for NoSQL. Each document contains 30 properties. Queries filter only on deviceId and timestamp. Write operations consume more RUs than expected. You need to reduce RU consumption for write operations while maintaining query performance. What should you do?", "o": ["Exclude unused properties from indexing.", "Configure selective indexing on queried properties.", "Migrate to a different partition key.", "Enable strong consistency for all requests."], "e": "By default Cosmos DB indexes every property, and each indexed property adds write RUs. Excluding the properties you never query keeps deviceId and timestamp indexed while making writes cheaper.", "a": 0},
{"id": "eh-46", "topic": "pg", "src": "imported", "num": 46, "type": "order", "q": "A recommendation system stores 3 million embeddings in Azure Database for PostgreSQL. During peak hours, P95 similarity-query latency increases, and the cache hit ratio drops significantly. You suspect that the vector index working set no longer fits in memory, resulting in more disk reads. You need to scale server resources and validate the outcome. Which four actions should you perform in sequence?", "items": ["Before peak hours, run a fixed workload to capture baseline P95 latency and capture EXPLAIN ANALYZE for the vector query.", "Review memory pressure and cache hit ratio during peak hours and compare them to the baseline.", "Scale to a tier with more memory per vCore.", "Re-run the same benchmark and compare P95 and P99 latency."], "extra": ["Increase embedding dimensionality.", "Disable autovacuum."], "e": "Measure a baseline, confirm the memory problem against it, scale to a memory-optimized tier, then re-run the same benchmark to prove the change helped."},
{"id": "eh-47", "topic": "redis", "src": "imported", "num": 47, "q": "You are implementing the expiration requirement for AI-generated summaries in the Redis cache. You need to purge the AI summaries five minutes after creation, regardless of how often they are accessed. What should you do?", "o": ["Set the maxmemory-policy to allkeys-lru.", "Configure absolute expiration on each cache key.", "Use the PERSIST command after each successful read operation.", "Implement sliding expiration on each cache key."], "e": "Absolute expiration (a TTL set once at creation) removes the key after five minutes no matter how often it's read. Sliding expiration and PERSIST would keep busy keys alive.", "a": 1},
{"id": "eh-48", "topic": "redis", "src": "imported", "num": 48, "q": "You optimize an AI inference API that uses Redis caching. You must reduce the risk of serving outdated data while minimizing cache management overhead. You need to implement the caching strategy that satisfies the requirements. What should you do?", "o": ["Trigger invalidation when source data changes.", "Set eviction policy to allkeys-lru.", "Increase memory allocation.", "Reset expiration on each read."], "e": "Invalidating keys when the source data changes removes stale entries at the moment they become stale, without constant manual cache management.", "a": 0},
{"id": "eh-49", "topic": "redis", "src": "imported", "num": 49, "q": "You are implementing semantic retrieval for a chatbot. Embeddings are already stored in Redis. However, vector similarity queries do not return matches. You need to resolve the vector similarity search issue. What should you do?", "o": ["Configure a metadata-only secondary index.", "Enable geo-replication.", "Create a FLAT vector index on the embedding field.", "Set a 24-hour Time to Live (TTL) on embedding keys."], "e": "Storing vectors isn't enough: Redis needs a search index with a vector field (FLAT or HNSW, created with FT.CREATE) before it can run similarity queries.", "a": 2},
{"id": "eh-50", "topic": "redis", "src": "imported", "num": 50, "type": "select", "q": "You are building a semantic search feature for a chatbot. You store document embeddings in Redis. You review the following Python code that connects to Redis and stores an embedding value:", "code": "01 import numpy as np\n02 from redis import Redis\n03 embedding = np.array([0.12, 0.98, 0.44], dtype=np.float32).tobytes()\n04 r = Redis(\n05     host=\"myredis.redis.cache.windows.net\",\n06     port=6380,\n07     password=\"accesskey\",\n08     ssl=True\n09 )\n10 r.hset(\"doc:1\", mapping={\"embedding\": embedding})\n11 r.expire(\"doc:1\", 600)", "slots": [{"l": "The embedding is stored as a hash field.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "The code enables similarity search on the embedding field.", "c": ["Yes", "No"], "a": "No"}, {"l": "The key will expire after 10 minutes.", "c": ["Yes", "No"], "a": "Yes"}], "e": "HSET stores the bytes in a hash field. Similarity search also needs a search index with a VECTOR field (FT.CREATE), which this code doesn't create. EXPIRE with 600 seconds is 10 minutes."},
{"id": "eh-51", "topic": "cosmos", "src": "imported", "num": 51, "case": "proseware", "type": "select", "q": "You need to configure vector embedding updates according to the business and technical requirements. Which configurations should you use?", "slots": [{"l": "Identify document changes that should trigger vectorization.", "c": ["Change feed processor", "Periodic full container scan", "Cross-partition SELECT query"], "a": "Change feed processor"}, {"l": "Scale out the vectorization processing.", "c": ["Lease container", "Strong consistency level", "RU throughput on the container"], "a": "Lease container"}], "e": "The change feed lists new and updated documents without scanning the container. The lease container lets several processor instances share the partitions, which is how the work scales out."},
{"id": "eh-52", "topic": "cosmos", "src": "imported", "num": 52, "case": "proseware", "q": "You need to address the known issue resulting from vector similarity queries. Which two actions should you perform?", "type": "multi", "o": ["Add a composite index on the vector fields and metadata properties of the container.", "Modify the indexing precision of the vector fields.", "Set the account consistency level to Strong.", "Change the vector index type from Oat to quantizedFlat or diskANN."], "c": [1, 3], "e": "Lowering the precision of stored vectors (quantization) and moving from a flat index to quantizedFlat or DiskANN both reduce the RU cost of similarity queries. Composite indexes and Strong consistency don't help vector search cost."},
{"id": "eh-53", "topic": "func", "src": "imported", "num": 53, "type": "select", "q": "You have an Azure Functions app using the Consumption hosting plan for a company. The app contains the following functions: You plan to enable dynamic concurrency on the app. The company requires that each function has its concurrency level managed separately. You need to configure the app for dynamic concurrency. Which file or function names should you use?", "code": "Function name | Trigger type\nf1            | HTTP\nf2            | Timer\nf3            | Azure Queues", "slots": [{"l": "File name", "c": ["function.json", "host.json", "local.settings.json"], "a": "host.json"}, {"l": "Function name", "c": ["f1", "f2", "f3"], "a": "f1"}], "e": "Dynamic concurrency is turned on in host.json (\"concurrency\": { \"dynamicConcurrencyEnabled\": true }). The answer key picks f1. Note that Microsoft's documentation lists queue, blob and Service Bus triggers as supported, which would point to f3."},
{"id": "eh-54", "topic": "cosmos", "src": "imported", "num": 54, "type": "select", "q": "You provisioned an Azure Cosmos DB for NoSQL account named account1 with the default consistency level. You plan to configure the consistency level on a per request basis. The level needs to be set for consistent prefix for read and write operations to account1. You need to identify the resulting consistency level for read and write operations. Which levels should you configure?", "slots": [{"l": "Read operations", "c": ["strong", "session", "consistent prefix"], "a": "consistent prefix"}, {"l": "Write operations", "c": ["strong", "session", "consistent prefix"], "a": "session"}], "e": "Request-level consistency can only relax reads, so reads use consistent prefix. Writes always use the account default, which is session for a new account."},
{"id": "eh-55", "topic": "cosmos", "src": "imported", "num": 55, "type": "select", "q": "You have an Azure Web app that uses Azure Cosmos DB as a data store. You create a Cosmos DB container by running the following PowerShell script: You create the following queries that target the container:", "code": "$partitionKeyPath = \"/EmployeeId\"\n$autoscaleMaxThroughput = 5000\n\nNew-AzCosmosDBSqlContainer `\n  -ResourceGroupName $resourceGroupName -AccountName $accountName `\n  -DatabaseName $databaseName -Name $containerName `\n  -PartitionKeyKind Hash -PartitionKeyPath $partitionKeyPath `\n  -AutoscaleMaxThroughput $autoscaleMaxThroughput\n\nQuery 1: SELECT * FROM c WHERE c.EmployeeId &gt; '12345'\nQuery 2: SELECT * FROM c WHERE c.UserId = '12345'", "slots": [{"l": "The minimum throughput for the container is 400 RU/s.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "The first query statement is an in-partition query.", "c": ["Yes", "No"], "a": "No"}, {"l": "The second query statement is a cross-partition query.", "c": ["Yes", "No"], "a": "Yes"}], "e": "A range filter on the partition key (&gt;) can span many partitions, so query 1 isn't an in-partition query, and query 2 filters on a property that isn't the partition key, so it fans out. The key says Yes to 400 RU/s; note that autoscale scales between 10% and 100% of the maximum, which for 5000 would be 500 RU/s."},
{"id": "eh-56", "topic": "func", "src": "imported", "num": 56, "case": "proseware", "q": "You need to configure Azure Functions to generate vector embeddings according to planned environment application architecture. Which trigger type should you use?", "o": ["Event Grid", "Azure Cosmos DB", "HTTP", "Service Bus"], "e": "Embeddings must be generated for new or updated Cosmos DB documents. The Azure Cosmos DB trigger reads the change feed and fires for exactly those changes.", "a": 1},
{"id": "eh-57", "topic": "acr", "src": "imported", "num": 57, "case": "proseware", "type": "select", "q": "You need to configure image build automation based on the technical requirements. Which settings should you configure?", "slots": [{"l": "Trigger for container images build", "c": ["Commit", "Scheduled", "Base image update"], "a": "Commit"}, {"l": "Implementation of image builds", "c": ["ACR Task", "GitHub workflow", "Docker Compose configuration"], "a": "ACR Task"}], "e": "Images must be built and validated on code changes, inside ACR, with no external build service. That's an ACR Task triggered by commits."},
{"id": "eh-58", "topic": "aks", "src": "imported", "num": 58, "case": "proseware", "q": "You need to deploy a batch embedding workload according to the planned application architecture. What should you use?", "o": ["YAML-formatted files", "kubectl run and create commands", "XML-formatted files", "az aks commands"], "e": "Deployments must come from version-controlled templates rather than ad hoc commands, so the AKS workload is defined in YAML manifests stored in source control.", "a": 0},
{"id": "eh-59", "topic": "aca", "src": "imported", "num": 59, "q": "An ACA app processes messages from an Azure Storage queue. The app must scale automatically based on messages in a specific Azure Storage queue by using a Kubernetes Event-driven Autoscaler (KEDA) custom scale rule. You need to configure the required scale rule values. Which two values should you configure?", "type": "multi", "o": ["Queue name", "Polling interval", "Trigger type", "Maximum replicas"], "c": [0, 2], "e": "A KEDA custom scale rule needs its type (azure-queue) and its metadata, which includes the queue name. Polling interval and maximum replicas have defaults and aren't what identifies the queue."},
{"id": "eh-60", "topic": "events", "src": "imported", "num": 60, "q": "You have an Event Grid subscription that triggers an Azure Function. You need to prevent loss of events in case the endpoint returns an HTTP 400 response. Which action should you perform?", "o": ["Implement optimistic batching.", "Implement asynchronous handshake validation.", "Configure a dead-letter destination.", "Configure a retry policy."], "e": "Event Grid doesn't retry on HTTP 400, because the request is treated as permanently bad. Only a dead-letter destination keeps those events from being lost.", "a": 2},
{"id": "eh-61", "topic": "events", "src": "imported", "num": 61, "q": "You are designing an Azure Function that will process orders from a new Azure Service Bus queue. You need to prevent the system from processing messages more than once and preserve failed messages for investigation. Which two actions should you implement?", "type": "multi", "o": ["Include a dead-letter handling process.", "Process orders by using an HTTP trigger.", "Enable duplicate detection on the queue.", "Enable sessions on Service Bus."], "c": [0, 2], "e": "Duplicate detection drops repeated messages with the same MessageId, and a dead-letter process keeps failed messages for investigation."},
{"id": "eh-62", "topic": "func", "src": "imported", "num": 62, "q": "You are designing an Azure Function app that exposes a public API. The solution must: Validate incoming request data and return results immediately to the caller. Support Microsoft Entra ID authentication. Guarantee idempotent processing when the same request is retried. Scale automatically under variable load. Avoid duplicate processing. You need to implement a trigger. Which trigger should you implement?", "o": ["Service Bus topic", "HTTP", "Azure Event Grid", "Azure Queue storage"], "e": "Only an HTTP trigger returns a result to the caller immediately and supports Entra ID authentication on the request. Idempotency is handled in code, for example with a request ID.", "a": 1},
{"id": "eh-63", "topic": "events", "src": "imported", "num": 63, "q": "A large retail company operates online and physical stores. The company tracks inventory levels in real time to manage stock efficiently across all locations. You develop an Azure Event Grid solution to handle events generated by the inventory management system deployed to Azure. You need to implement a subscription filter that dynamically adjusts to seasonal changes in product demand. Which event filter should you use?", "o": ["An advanced filter using a Boolean condition that evaluates multiple data fields, including a season field within the event data", "A prefix filter on the event type field that matches the current season's name", "A subscription filter that uses a label filter to include events tagged with seasonal promotional codes", "A static subject filter that targets events with a subject ending in \"/seasonal/inventory\""], "e": "Advanced filters evaluate values inside the event data, so a condition on a season field can change with demand. Prefix, label and static subject filters can't look inside the payload like that.", "a": 0},
{"id": "eh-64", "topic": "sec", "src": "imported", "num": 64, "q": "You are developing an Azure Function that calls external APIs by providing an access token for the API. The access token is stored in a secret named token in an Azure Key Vault named mykeyvault. You need to ensure the Azure Function can access the token. Which value should you store in the Azure Functions app configuration?", "o": ["KeyVault:mykeyvault;Secret:token", "App:Settings:Secret:mykeyvault:token", "@Microsoft.KeyVault(SecretUri=https://mykeyvault.vault.azure.net/secrets/token/)", "AZUREKVCONNSTR_ https://mykeyvault.vault.azure.net/secrets/token/"], "e": "A Key Vault reference in app settings uses the @Microsoft.KeyVault(SecretUri=...) syntax. The function app's managed identity needs permission to read the secret.", "a": 2},
{"id": "eh-65", "topic": "events", "src": "imported", "num": 65, "q": "You process Azure Service Bus messages that require a dependent external API call. If the API is temporarily unavailable, you must delay processing of the message without incrementing the delivery count. You need to find a way to process the message when the API is available while keeping the message accessible. Which message action should you perform?", "o": ["Dead-letter", "Defer", "Abandon", "Complete"], "e": "Deferring keeps the message in the queue, set aside, without incrementing the delivery count. You retrieve it later by its sequence number once the API is back.", "a": 1},
{"id": "eh-66", "topic": "events", "src": "imported", "num": 66, "type": "select", "q": "You configure an Event Grid event subscription that routes AI file-upload events to an Azure Function endpoint. Events must be delivered only in the following conditions: The event path starts with /uploads/ai/. The payload property data.fileType is \"pdf.\" You must store undelivered events for later investigation and reprocessing if the subscriber endpoint cannot accept an event after multiple retries. You need to configure the filtering and reliability settings. Which configurations should you use?", "slots": [{"l": "Path prefix condition", "c": ["Subject filter", "Advanced filter", "Message session"], "a": "Subject filter"}, {"l": "Payload property condition", "c": ["Subject filter", "Advanced filter", "Event type filter"], "a": "Advanced filter"}, {"l": "Undelivered events", "c": ["Subject filter", "Duplicate detection", "Dead-letter destination"], "a": "Dead-letter destination"}], "e": "Subject filters match the start (subjectBeginsWith) or end of the subject path. Advanced filters look inside the event data, such as data.fileType. A dead-letter destination stores events that can't be delivered after retries."},
{"id": "eh-67", "topic": "events", "src": "imported", "num": 67, "type": "select", "q": "You are creating an app that uses Event Grid to connect with other services. Your app's event data will be sent to a serverless function that checks compliance. This function is maintained by your company. You write a new event subscription at the scope of your resource. The event must be invalidated after a specific period of time. You need to configure Event Grid. What should you do?", "slots": [{"l": "WebHook event delivery", "c": ["SAS tokens", "Key authentication", "Management Access Control"], "a": "Key authentication"}, {"l": "Topic publishing", "c": ["ValidationCode handshake", "ValidationURL handshake", "JWT token"], "a": "ValidationCode handshake"}], "e": "The answer key pairs key authentication with the ValidationCode handshake, the synchronous way an endpoint you control (such as your own function) proves it wants the events."},
{"id": "eh-68", "topic": "events", "src": "imported", "num": 68, "type": "select", "q": "You have an Azure Service Bus namespace that contains a topic named Topic1. You plan to create a subscription named Sub1 to Topic1. In Sub1, you plan to filter messages from Topic1 based on their system properties and apply an action that will annotate each filtered message. You need to configure the filtering. How should you configure the filtering?", "slots": [{"l": "Filter type", "c": ["Use the SQL type.", "Use the Boolean type.", "Use the Correlation type."], "a": "Use the SQL type."}, {"l": "Filtering action", "c": ["Copy a message and update its body.", "Copy a message and annotate its metadata.", "Annotate the metadata of the original message."], "a": "Copy a message and annotate its metadata."}], "e": "Only SQL filters can have an action. The action changes properties on the copy of the message delivered to the subscription, not on the original or its body."},
{"id": "eh-69", "topic": "func", "src": "imported", "num": 69, "type": "select", "q": "You plan to develop an Azure Functions app with an HTTP trigger. The app must support the following functionality: Event-driven scaling - Ability to use custom Linux images for function execution You need to identify the app's hosting plan and the maximum amount of time that the app function can take to respond to incoming requests. Which configuration setting values should you use?", "slots": [{"l": "Hosting plan", "c": ["Consumption", "Dedicated", "Premium"], "a": "Premium"}, {"l": "Timeout value", "c": ["230 seconds", "10 minutes", "unlimited"], "a": "unlimited"}], "e": "Premium gives event-driven scaling and supports custom Linux images. The key says the timeout is unlimited (Premium's function timeout can be unbounded). Be aware that an HTTP-triggered function still has to respond within 230 seconds because of the Azure load balancer."},
{"id": "eh-70", "topic": "events", "src": "imported", "num": 70, "type": "select", "q": "You are reviewing the message-processing code in a backend worker service. You review the following Python code that initializes and starts a Service Bus processor.", "code": "01 import json\n02 from azure.servicebus import ServiceBusClient, ServiceBusReceiveMode\n03 from azure.identity import DefaultAzureCredential\n04 credential = DefaultAzureCredential()\n05 with client.get_queue_receiver(\n06     queue_name=\"inference-requests\",\n07     receive_mode=ServiceBusReceiveMode.PEEK_LOCK,\n08     max_wait_time=30\n09 ) as receiver:\n10     for msg in receiver:\n11         try:\n12             payload = json.loads(str(msg))\n13             result = run_inference(payload)\n14             save_result(result, payload.get(\"document_id\"))\n15             receiver.complete_message(msg)\n16         except json.JSONDecodeError:\n17             receiver.dead_letter_message(msg, reason=\"MalformedPayload\",\n18                 error_description=\"Message body is not valid JSON\")\n22         except ModelNotFoundError:\n23             receiver.dead_letter_message(msg, reason=\"UnsupportedModel\", ...)\n28         except TransientServiceError:\n29             receiver.abandon_message(msg)", "slots": [{"l": "Messages are removed from the queue as soon as they are received by the processor.", "c": ["Yes", "No"], "a": "No"}, {"l": "If message processing fails due to a transient service error, the message can be retried by another consumer.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "Messages with invalid JSON payloads are retried until the maximum delivery count is reached.", "c": ["Yes", "No"], "a": "Yes"}], "e": "PEEK_LOCK keeps the message in the queue until it is completed, and abandon_message releases the lock so another consumer can retry it. The key says Yes to the third statement, but the code dead-letters invalid JSON straight away (line 17), so it isn't retried; No looks more accurate."},
{"id": "eh-71", "topic": "events", "src": "imported", "num": 71, "type": "select", "q": "You are developing a solution that uses several Azure Service Bus queues. You create an Azure Event Grid subscription for the Azure Service Bus namespace. You use Azure Functions as subscribers to process the messages. You need to emit events to Azure Event Grid from the queues. You must use the principle of least privilege and minimize costs. Which Azure Service Bus values should you use?", "slots": [{"l": "Tier", "c": ["Basic", "Standard", "Premium"], "a": "Premium"}, {"l": "Access control (IAM) level", "c": ["Contributor", "Data Receiver", "Data Sender", "Data Owner"], "a": "Data Receiver"}], "e": "Service Bus only emits events to Event Grid from the Premium tier. The functions only read messages, so Azure Service Bus Data Receiver is the least-privilege role."},
{"id": "eh-72", "topic": "func", "src": "imported", "num": 72, "type": "select", "q": "You are creating an Azure Functions app project in your local development environment by using Azure Functions Core Tools. You must create the project in either Python or C# without using a template. You need to specify the command and its parameter required to create the Azure Functions app project. Which command and parameter should you specify?", "slots": [{"l": "Command", "c": ["func new", "func init", "func azure"], "a": "func init"}, {"l": "Parameter", "c": ["--language", "--worker-runtime", "--target-framework"], "a": "--worker-runtime"}], "e": "func init creates a new Functions project, and --worker-runtime (for example python or dotnet) picks the language without prompting for a template. func new adds a function to an existing project."},
{"id": "eh-73", "topic": "func", "src": "imported", "num": 73, "q": "You are designing an Azure Function app that processes large image uploads submitted by users through an HTTP endpoint. The solution must: <br>• Prevent client timeouts by decoupling image processing from the initial upload request. <br>• Support automatic retry behavior for failed processing attempts. <br>• Scale the background processing independently of the rate of incoming HTTP uploads. You need to design a scalable and reliable asynchronous processing solution. Which two actions should you implement?", "type": "multi", "o": ["Implement a queue-triggered function for image processing.", "Configure retry policies on a storage queue.", "Process the image inside the HTTP-triggered function.", "Persist upload metadata to Azure Storage."], "c": [0, 3], "e": "The HTTP function stores the upload and its metadata, then hands processing to a queue-triggered function. The queue decouples the work, retries failures, and scales on its own."},
{"id": "eh-74", "topic": "func", "src": "imported", "num": 74, "type": "select", "q": "You are reviewing an Azure Function app that processes incoming order requests for a company. The function must - <br>• Accept order submissions from an external client application. <br>• Require controlled access for security. <br>• Return a response containing the processed request payload. You review the following code segment:", "code": "01 [FunctionName(\"ProcessOrder\")]\n02 public static async Task&lt;IActionResult&gt; Run(\n03   [HttpTrigger(AuthorizationLevel.Function, \"post\")] HttpRequest req,\n04   ILogger log)\n05 {\n06   string result = await new StreamReader(req.Body).ReadToEndAsync();\n07   return new OkObjectResult(result);\n08 }", "slots": [{"l": "The function requires a key for invocation.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "The function supports HTTP GET requests.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "The response returns the request body.", "c": ["Yes", "No"], "a": "No"}, {"l": "The function validates the request body before returning a response.", "c": ["Yes", "No"], "a": "No"}], "e": "AuthorizationLevel.Function requires a function key, and nothing validates the body. The key answers Yes for GET and No for returning the body, but the code only lists \"post\" and returns the body it read (lines 6–7), so No and Yes look more accurate for those two."},
{"id": "eh-75", "topic": "func", "src": "imported", "num": 75, "type": "match", "q": "You are designing Azure Functions for three different backend workloads. Each workload requires one of the following dispatching models: <br>• Return an immediate response to a client. <br>• Process background work from a queue. <br>• Run code on a fixed schedule. You need to select the trigger for each requirement. Which triggers should you select?", "pairs": [["Return an immediate response to a client.", "HTTP trigger"], ["Process background work from a queue.", "Queue Storage trigger"], ["Run code on a fixed schedule.", "Timer trigger"]], "extra": ["Event Grid trigger", "Blob Storage trigger"], "e": "HTTP triggers answer the caller directly, queue triggers process messages in the background, and timer triggers run on a CRON schedule."},
{"id": "eh-76", "topic": "events", "src": "imported", "num": 76, "type": "select", "q": "You plan to configure an Event Grid subscription for AI inference events. The solution must: <br>• Filter events by payload data. <br>• Retain undelivered events. <br>• Limit retry attempts. You need to configure the Event Grid. Which configurations should you use?", "slots": [{"l": "Filter events by payload data.", "c": ["Advanced filter", "Subject filter", "Service Bus session"], "a": "Advanced filter"}, {"l": "Retain undelivered events.", "c": ["Dead-letter destination", "Endpoint validation", "Duplicate detection"], "a": "Dead-letter destination"}, {"l": "Limit retry behavior.", "c": ["Maximum delivery attempts", "Message sessions", "Auto-complete"], "a": "Maximum delivery attempts"}], "e": "Advanced filters read values from the event data, a dead-letter destination keeps events that can't be delivered, and the retry policy's maximum delivery attempts caps retries."},
{"id": "eh-77", "topic": "events", "src": "imported", "num": 77, "type": "order", "q": "You have a newly provisioned Azure subscription. You are designing a custom Event Grid workflow for AI inference events. You need to implement the Event Grid components to support routing of high-confidence events to a downstream processor. Which three actions should you perform in sequence?", "items": ["Register the provider.", "Create a custom topic.", "Create an event subscription."], "extra": ["Create a domain.", "Create a partner topic."], "e": "A new subscription must register the Microsoft.EventGrid resource provider first. Your own events are published to a custom topic, and an event subscription (with an advanced filter on confidence) routes them to the processor."},
{"id": "eh-78", "topic": "events", "src": "imported", "num": 78, "q": "You publish custom AI inference events to an Event Grid topic. Downstream services must receive events only if the confidenceScore value is greater than 0.80. You need to filter events based on a numeric value in the event payload. Which filter should you configure?", "o": ["event type", "subject", "advanced"], "e": "Advanced filters can compare numeric values in the event data, for example NumberGreaterThan on data.confidenceScore with 0.80.", "a": 2},
{"id": "eh-79", "topic": "events", "src": "imported", "num": 79, "type": "match", "q": "You are building a back-end pipeline that receives AI inference requests. The pipeline must perform the following actions: <br>• Publish a message so that multiple independent consumers receive it. <br>• Process messages in first-in, first-out (FIFO) order. <br>• Isolate any failed messages. You need to configure the appropriate Service Bus entities. How should you configure the Service Bus entities?", "pairs": [["Publish a message for multiple consumers to receive.", "topic"], ["Process messages in FIFO order.", "queue"], ["Isolate any failed messages.", "dead-letter queue"]], "extra": ["subscription rule", "subscription filter", "auto-forward destination"], "e": "A topic gives every subscriber its own copy, and the dead-letter queue holds failed messages. For FIFO, the PDF's answer text names message sessions, which aren't in the list; a queue is the closest choice, and enabling sessions on it is what actually guarantees ordering."},
{"id": "eh-80", "topic": "events", "src": "imported", "num": 80, "q": "An Azure Storage Blob upload must trigger backend processing. The solution must: <br>• Avoid polling. <br>• Minimize latency. <br>• Trigger automatically when the upload occurs. You need to ensure that processing starts as soon as a file is uploaded. Which trigger should you implement?", "o": ["Timer", "Event Grid", "Queue storage", "HTTP"], "e": "Blob storage publishes BlobCreated events to Event Grid, which pushes them to the handler immediately with no polling.", "a": 1},
{"id": "eh-81", "topic": "events", "src": "imported", "num": 81, "q": "An Azure Service Bus queue processes AI enrichment jobs. Some messages fail repeatedly because the payload is malformed. You need to ensure that repeatedly failing messages do NOT block valid messages and can be inspected separately. Which message action should you perform?", "o": ["complete", "defer", "dead-letter", "abandon"], "e": "Dead-lettering moves a poison message to the dead-letter subqueue, where it no longer blocks valid messages and can be inspected later.", "a": 2},
{"id": "eh-82", "topic": "func", "src": "imported", "num": 82, "q": "An HTTP-triggered Azure Function must read a JSON configuration file stored in Azure Blob Storage. You need to retrieve the configuration file contents. What should you use?", "o": ["Output binding", "Input binding", "Timer trigger", "HTTP trigger"], "e": "An input binding reads data (here a blob) into the function when it runs, so you don't write Storage SDK code.", "a": 1},
{"id": "eh-83", "topic": "events", "src": "imported", "num": 83, "q": "You are designing a messaging solution by using Service Bus for AI document processing. You need to ensure that a published message is delivered to multiple independent consumers. Each consumer must receive their own copy of the message. Which two Service Bus entities should you use?", "type": "multi", "o": ["topic", "subscription", "queue", "dead-letter queue", "message session"], "c": [0, 1], "e": "A Service Bus topic with one subscription per consumer gives each consumer its own copy of every message. A queue delivers each message to only one receiver."},
{"id": "eh-84", "topic": "acr", "src": "imported", "num": 84, "case": "fabrikam", "q": "You need to configure image builds for a new service to meet the technical requirements. Which two actions should you perform?", "type": "multi", "o": ["Deploy the container image to Azure Kubernetes Service.", "Create a GitHub Action to rebuild the application on every push.", "Configure a base image update trigger for the ACR Task.", "Create and configure an ACR Task with a source repository context.", "Create an Azure DevOps pipeline with a source repository context.", "Push updated code to the source repository."], "c": [3, 5], "e": "Images must be built by ACR Tasks when source code is committed. Create the ACR Task with the source repository as context; pushing code to that repository then triggers the build."},
{"id": "eh-85", "topic": "func", "src": "imported", "num": 85, "case": "proseware", "q": "You need to deploy Azure Function resources and apps to meet the business and technical requirements. What should you use?", "o": ["GitHub Actions", "Azure Functions Core Tools", "Azure CLI", "Local Git deployment"], "e": "Deployments must go through an automated, version-controlled pipeline using Bicep. GitHub Actions does that. Core Tools, Azure CLI and local Git are command-line or local deployments.", "a": 0},
{"id": "eh-87", "topic": "events", "src": "imported", "num": 87, "q": "You are creating a hazard notification system that has a single signaling server which triggers audio and visual alarms to start and stop. You implement Azure Service Bus to publish alarms. Each alarm controller uses Azure Service Bus to receive alarm signals as part of a transaction. Alarm events must be recorded for audit purposes. Each transaction record must include information about the alarm type that was activated. You need to implement a reply trail auditing solution. Which two actions should you perform?", "type": "multi", "o": ["Assign the value of the hazard message SessionID property to the ReplyToSessionId property.", "Assign the value of the hazard message MessageId property to the SequenceNumber property.", "Assign the value of the hazard message SequenceNumber property to the DeliveryCount property.", "Assign the value of the hazard message SessionID property to the SequenceNumber property.", "Assign the value of the hazard message MessageId property to the DeliveryCount property.", "Assign the value of the hazard message MessageId property to the CorrelationId property."], "c": [0, 5], "e": "For a reply trail, copy the request's SessionId into ReplyToSessionId and its MessageId into CorrelationId, so each reply can be linked to the alarm that caused it."},
{"id": "eh-88", "topic": "events", "src": "imported", "num": 88, "q": "A company is implementing a publish-subscribe (Pub/Sub) messaging component by using Azure Service Bus. You are developing the first subscription application. In the Azure portal you see that messages are being sent to the subscription for each topic. You create and initialize a subscription client object by supplying the correct details, but the subscription application is still not consuming the messages. You need to ensure that the subscription client processes all messages. Which code segment should you use?", "o": ["subscriptionClient = new SubscriptionClient(ServiceBusConnectionString, TopicName, SubscriptionName);", "subscriptionClient.RegisterMessageHandler(ProcessMessagesAsync, messageHandlerOptions);", "await subscriptionClient.AddRuleAsync(new RuleDescription(RuleDescription.DefaultRuleName, new TrueFilter()));", "await subscriptionClient.CloseAsync();"], "e": "Creating the client isn't enough. Registering a message handler starts the message pump that actually receives and processes messages.", "a": 1},
{"id": "eh-89", "topic": "events", "src": "imported", "num": 89, "q": "You are implementing an application by using Azure Event Grid to push near-real-time information to customers. You have the following requirements: <br>• You must send events to thousands of customers that include hundreds of various event types. <br>• The events must be filtered by event type before processing. <br>• Authentication and authorization must be handled by using Microsoft Entra ID. <br>• The events must be published to a single endpoint. You need to implement Azure Event Grid. Solution: Publish events to a partner topic. Create an event subscription for each customer. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "The answer key says Yes. Note that Event Grid domains are the feature usually recommended for publishing to thousands of customers through one endpoint, with per-customer topics and Entra ID authorization.", "a": 0, "fixed": true},
{"id": "eh-90", "topic": "events", "src": "imported", "num": 90, "q": "You are implementing an application by using Azure Event Grid to push near-real-time information to customers. You have the following requirements: <br>• You must send events to thousands of customers that include hundreds of various event types. <br>• The events must be filtered by event type before processing. <br>• Authentication and authorization must be handled by using Microsoft Entra ID. <br>• The events must be published to a single endpoint. You need to implement Azure Event Grid. Solution: Publish events to a custom topic. Create an event subscription for each customer. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "A single custom topic with one subscription per customer doesn't give per-customer authorization through Entra ID at the scale required. Event Grid domains are designed for that scenario.", "a": 1, "fixed": true},
{"id": "eh-91", "topic": "events", "src": "imported", "num": 91, "q": "You are implementing an application by using Azure Event Grid to push near-real-time information to customers. You have the following requirements: <br>• You must send events to thousands of customers that include hundreds of various event types. <br>• The events must be filtered by event type before processing. <br>• Authentication and authorization must be handled by using Microsoft Entra ID. <br>• The events must be published to a single endpoint. You need to implement Azure Event Grid. Solution: Publish events to a system topic. Create an event subscription for each customer. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "System topics carry events from Azure services, not events your application publishes, so they can't be used here.", "a": 1, "fixed": true},
{"id": "eh-92", "topic": "events", "src": "imported", "num": 92, "type": "order", "q": "You are provisioning and configuring a Service Bus processor for AI batch jobs. The processor must connect to an existing queue, register handlers for message and error processing, and then begin receiving messages. You need to provision and configure the Service Bus processor for message and error handling. Which four actions should you perform in sequence?", "items": ["Create the Service Bus client.", "Create the Service Bus processor for the queue.", "Register message and error handlers.", "Start the message processor."], "extra": ["Dead-letter failed messages."], "e": "The client connects to the namespace, the processor is created for the queue, handlers are attached (ProcessMessageAsync and ProcessErrorAsync), and only then is processing started."},
{"id": "eh-93", "topic": "sec", "src": "imported", "num": 93, "case": "fabrikam", "q": "You need to implement a secret management solution for the Recommendation API to satisfy the security and identity requirements of Fabrikam Inc. Which service should you use?", "o": ["Container environment variables", "Azure App Configuration", "Kubernetes secrets", "Azure Key Vault"], "e": "Secrets must be stored centrally and rotated automatically, with managed identity access. Azure Key Vault does all three.", "a": 3},
{"id": "eh-94", "topic": "aks", "src": "imported", "num": 94, "case": "fabrikam", "type": "match", "q": "You need to troubleshoot connectivity failures between microservices running in AKS. Which troubleshooting actions should you perform?", "pairs": [["Service fails to communicate with another service.", "Inspect Kubernetes service endpoints."], ["Pod restarts repeatedly.", "Inspect container logs."], ["Readiness probe failures are observed.", "Inspect Kubernetes events."]], "extra": ["Inspect Pod descriptions."], "e": "Service-to-service failures usually come from a Service with no or wrong endpoints. Restarting containers explain themselves in their logs, and probe failures are recorded as Kubernetes events."},
{"id": "eh-95", "topic": "mon", "src": "imported", "num": 95, "case": "proseware", "type": "order", "q": "You need to implement trace correlation according to the business requirements. Which three actions should you perform in sequence?", "items": ["Instrument the application code by using the OpenTelemetry SDK.", "Configure a trace exporter in the OpenTelemetry SDK.", "Redeploy the instrumented services."], "extra": ["Call TelemetryClient.TrackEvent() within service methods.", "Implement a view in the OpenTelemetry SDK."], "e": "Add OpenTelemetry instrumentation, configure an exporter (such as the Azure Monitor exporter) so traces reach Application Insights, then redeploy. TelemetryClient is the older Application Insights SDK, which the requirements rule out."},
{"id": "eh-96", "topic": "aca", "src": "imported", "num": 96, "case": "proseware", "type": "match", "q": "You need to configure event-driven scaling for the backend API services to meet the technical requirements. Which settings should you use for each element?", "pairs": [["Scaler", "Azure Service Bus"], ["Trigger metadata", "messageCount"], ["min-replicas", "0"]], "extra": ["1", "queueLength", "Azure Container Apps"], "e": "ACA must scale on pending Service Bus messages, so use the azure-servicebus KEDA scaler with its messageCount metadata. The key sets min-replicas to 0; note the case also asks to minimize cold starts, which a minimum of 1 would do."},
{"id": "eh-97", "topic": "sec", "src": "imported", "num": 97, "q": "You deploy a production Azure Function app that connects to an Azure SQL Database. The solution must provide the following functionality: Prevent secrets from being exposed in source control. Support secret rotation without redeploying the function app. Avoid downtime during credential updates. You need to configure secure and maintainable secret management. What should you configure?", "o": ["Application settings with Key Vault references", "Environment variables in local.settings.json", "Hard-coded connection string in the startup class", "Parameter file stored in source control"], "e": "App settings that use Key Vault references keep secrets out of source control, and pointing at the secret without a version picks up rotated values without redeploying.", "a": 0},
{"id": "eh-98", "topic": "sec", "src": "imported", "num": 98, "q": "An AI platform uses App Configuration for feature flags and endpoint routing. The platform stores secrets alongside configuration data and does NOT support dynamic refresh. The solution must support dynamic configuration refresh while ensuring that secrets are NOT stored in App Configuration. You need to enable secure dynamic configuration management for the platform. Which three actions should you perform?", "type": "multi", "o": ["Allow configuration updates with a polling interval.", "Use managed identity for both App Configuration and Key Vault access.", "Store API keys in Key Vault.", "Use a service principal secret for both App Configuration and Key Vault access.", "Store configuration values in environment variables."], "c": [0, 1, 2], "e": "Move API keys to Key Vault, use a managed identity for both App Configuration and Key Vault, and enable dynamic refresh with a polling interval. Service principal secrets are just another credential to store."},
{"id": "eh-99", "topic": "sec", "src": "imported", "num": 99, "q": "You are developing an AI application. The application configuration will depend on a dynamically retrieved value of a designated key stored in an Azure App Configuration resource. You must deploy the application to the test, staging, and production environments. You need to be able to set the value differently in each environment. Which feature of Azure App Configuration resource should you use?", "o": ["Labels", "Resource tags", "Content types", "Key prefixes"], "e": "Labels let the same key hold different values per environment, for example test, staging and production.", "a": 0},
{"id": "eh-100", "topic": "sec", "src": "imported", "num": 100, "q": "You are developing an AI-powered API that retrieves connection strings and API keys from Azure Key Vault. You must configure a solution that provides the following security functionality: The API must authenticate to Key Vault without storing credentials in any application configuration files. The identity used by the API must have only the minimum permissions necessary to read secrets. The configuration must minimize the blast radius if an identity or credential is compromised. You need to implement a secure access strategy for the API. Which two actions should you perform?", "type": "multi", "o": ["Assign the Key Vault Administrator role at subscription scope.", "Grant the Key Vault Secrets User role at vault scope.", "Use system-assigned managed identity.", "Store a secret value in Azure App Configuration."], "c": [1, 2], "e": "A managed identity removes stored credentials. Key Vault Secrets User at vault scope gives read-only access to secrets in that one vault, which keeps the blast radius small."},
{"id": "eh-101", "topic": "sec", "src": "imported", "num": 101, "q": "You are developing an AI API deployed to ACA. The API requires database credentials that are stored in Key Vault. Key Vault is configured to use Azure RBAC for access control. The database credentials are rotated periodically by the security team. The application must always use the latest version of each credential without being redeployed and without exposing secrets in code or configurations. You need to implement a secure secret access strategy that prevents credential exposure and fetches the latest version of each secret at runtime without redeploying the container. Which three actions should you perform?", "type": "multi", "o": ["Configure a Key Vault RBAC role assignment.", "Configure a Key Vault access policy.", "Export the secret during deployment.", "Assign a system-assigned managed identity.", "Retrieve the secret at runtime by using the SDK."], "c": [0, 3, 4], "e": "Use a system-assigned managed identity, grant it access with a Key Vault RBAC role assignment (access policies don't apply when the vault uses RBAC), and read the secret with the SDK at runtime so new versions are picked up."},
{"id": "eh-102", "topic": "sec", "src": "imported", "num": 102, "q": "You plan to deploy a container to an Azure App Service API app named api1. You host the source code for api1 in a GitHub repository. The container uses the API key at runtime to connect to a backend service. The container must be able to retrieve the API key at runtime without exposing it in the source repository or Git commit history. You need to ensure that the API key remains outside of Git commit history and is available to the container at runtime. Solution: Store the API key as a GitHub repository secret. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "GitHub secrets are only available to workflows at build time. They don't make the key available to the running container.", "a": 1, "fixed": true},
{"id": "eh-103", "topic": "sec", "src": "imported", "num": 103, "q": "You plan to deploy a container to an Azure App Service API app named api1. You host the source code for api1 in a GitHub repository. The container uses the API key at runtime to connect to a backend service. The container must be able to retrieve the API key at runtime without exposing it in the source repository or Git commit history. You need to ensure that the API key remains outside of Git commit history and is available to the container at runtime. Solution: Embed the API key as a hardcoded environment variable in the Dockerfile. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "A value in the Dockerfile ends up in the image and in the Git history, which is exactly what the requirement forbids.", "a": 1, "fixed": true},
{"id": "eh-104", "topic": "sec", "src": "imported", "num": 104, "q": "You plan to deploy a container to an Azure App Service API app named api1. You host the source code for api1 in a GitHub repository. The container uses the API key at runtime to connect to a backend service. The container must be able to retrieve the API key at runtime without exposing it in the source repository or Git commit history. You need to ensure that the API key remains outside of Git commit history and is available to the container at runtime. Solution: Store the API key in Azure Key Vault and reference it from an App Service application setting. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "A Key Vault reference in an App Service app setting keeps the key out of Git and exposes it to the container at runtime as an environment variable.", "a": 0, "fixed": true},
{"id": "eh-105", "topic": "sec", "src": "imported", "num": 105, "q": "You are preparing a production deployment for an Azure Function app. The app will run across multiple environments. The solution must support environment-specific configuration and prevent secrets from being stored in source control. You need to develop the solution. Solution: Store connection strings in the Function app application settings configured in the Azure Portal. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "Plain app settings are environment-specific, but they hold the secret values directly instead of keeping them in a secret store. The intended answer uses Key Vault.", "a": 1, "fixed": true},
{"id": "eh-106", "topic": "sec", "src": "imported", "num": 106, "q": "You are preparing a production deployment for an Azure Function app. The app will run across multiple environments. The solution must support environment-specific configuration and prevent secrets from being stored in source control. You need to develop the solution. Solution: Store production secrets in environment variables set by the Dockerfile. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "Environment variables set in a Dockerfile are baked into the image and committed with the source, so secrets end up in source control.", "a": 1, "fixed": true},
{"id": "eh-107", "topic": "sec", "src": "imported", "num": 107, "q": "You are preparing a production deployment for an Azure Function app. The app will run across multiple environments. The solution must support environment-specific configuration and prevent secrets from being stored in source control. You need to develop the solution. Solution: Use App Configuration with Key Vault references to store environment-specific settings and secrets, accessed from the function app by using a managed identity. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "App Configuration handles environment-specific settings (with labels), Key Vault references keep secrets out of source control, and a managed identity removes stored credentials.", "a": 0, "fixed": true},
{"id": "eh-108", "topic": "aca", "src": "imported", "num": 108, "type": "select", "q": "You are developing several microservices to run on Azure Container Apps. External HTTP ingress traffic has been enabled for the microservices. A deployed microservice must be updated to allow users to test new features. You have the following requirements: Enable and maintain a single URL for the updated microservice to provide to test users. Update the microservice that corresponds to the current microservice version. You need to configure Azure Container Apps. Which features should you configure?", "slots": [{"l": "Single URL for test users", "c": ["Revision label", "Revision mode", "Container image", "Container registry"], "a": "Revision label"}, {"l": "Current microservice activation", "c": ["Revision label", "Revision mode", "Container image", "Container registry"], "a": "Revision mode"}], "e": "A revision label gives a revision its own stable URL that you can move between revisions. Revision mode (multiple) controls whether the current revision stays active alongside the new one."},
{"id": "eh-109", "topic": "acr", "src": "imported", "num": 109, "type": "select", "q": "You deploy a private container image from Azure Container Registry (ACR) to App Service. App Service must authenticate to ACR to pull the image. The solution must NOT store static registry credentials. You need to configure the secure image pull authentication. Which configurations should you use?", "slots": [{"l": "Authenticate App Service to ACR.", "c": ["Assign the Container Registry Repository Reader role to a managed identity.", "Configure a webhook on ACR.", "Enable the admin user."], "a": "Assign the Container Registry Repository Reader role to a managed identity."}, {"l": "Avoid storing static credentials.", "c": ["Embed credentials in Dockerfile.", "Store the registry password in application settings.", "Use managed identity with role assignment."], "a": "Use managed identity with role assignment."}], "e": "App Service pulls the image with its managed identity, which holds a read role on the registry (AcrPull or the newer repository reader role). The admin user, a Dockerfile or app settings would all store a password."},
{"id": "eh-110", "topic": "sec", "src": "imported", "num": 110, "type": "select", "q": "You deploy a Linux container image to App Service. The container requires the following environment variables at runtime: A non-sensitive configuration value named MODEL_VERSION A database password that must remain secure You need to configure App Service to provide these environment variables at runtime. Which configurations should you use?", "slots": [{"l": "MODEL_VERSION", "c": ["App setting with plain text value", "Connection string", "Dockerfile ENV instruction"], "a": "App setting with plain text value"}, {"l": "Database password", "c": ["App setting with plain text value", "Connection string with embedded password", "Key Vault reference syntax"], "a": "Key Vault reference syntax"}], "e": "App settings reach the container as environment variables. A non-sensitive value can be plain text; a password should be an app setting with a Key Vault reference, so the secret stays in Key Vault."},
{"id": "eh-111", "topic": "mon", "src": "imported", "num": 111, "type": "select", "q": "You plan to deploy a web app to App Service on Linux. You create an App Service plan. You create and push a custom Docker image that contains the web app to Azure Container Registry. You need to access the console logs generated from inside the container in real-time. How should you complete the Azure CLI command?", "code": "az webapp log [1] --name ContosoWeb --resource-group ContosoDevRG\n  [2] filesystem\naz [3] log [4] --name ContosoWeb --resource-group ContosoDevRG", "slots": [{"l": "[1]", "c": ["config", "download", "show", "tail"], "a": "config"}, {"l": "[2]", "c": ["--web-server-logging", "--docker-container-logging", "--application-logging"], "a": "--docker-container-logging"}, {"l": "[3]", "c": ["webapp", "acr", "aks"], "a": "webapp"}, {"l": "[4]", "c": ["config", "download", "show", "tail"], "a": "tail"}], "e": "First turn on container logging to the file system with az webapp log config --docker-container-logging filesystem, then stream it live with az webapp log tail."},
{"id": "eh-112", "topic": "mon", "src": "imported", "num": 112, "type": "select", "q": "A Python web API uses OpenTelemetry for tracing. The call_downstream_service function makes an outbound HTTP request by using the requests library. The following code is the only OpenTelemetry configuration in the application:", "code": "01 from opentelemetry import trace\n02 tracer = trace.get_tracer(__name__)\n03 def process_request():\n04     with tracer.start_as_current_span(\"process_request\"):\n05         call_downstream_service()", "slots": [{"l": "The code creates a span for each request.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "The code automatically propagates trace context to downstream HTTP services.", "c": ["Yes", "No"], "a": "No"}, {"l": "The solution requires additional instrumentation for end-to-end trace correlation.", "c": ["Yes", "No"], "a": "Yes"}], "e": "start_as_current_span creates a span per call, but nothing injects the trace context into the outgoing requests call. You need the requests instrumentation (RequestsInstrumentor) or manual propagation for end-to-end correlation."},
{"id": "eh-113", "topic": "sec", "src": "imported", "num": 113, "type": "select", "q": "You are using Python SDK to develop a containerized AI application that retrieves the value of a runtime setting stored in an Azure App Configuration resource. The application will run in Azure in the security context of a managed identity. The application must work in a local development environment without any code changes. You need to complete the code that implements the retrieval. How should you complete the code?", "code": "var1 = [1]()\nvar2 = AppConfigurationClient(endpoint, var1)\nvar3 = var2.[2](\"FeatureX\", label=\"production\")", "slots": [{"l": "[1]", "c": ["ClientSecretCredential", "DefaultAzureCredential", "ManagedIdentityCredential"], "a": "DefaultAzureCredential"}, {"l": "[2]", "c": ["list_labels", "get_configuration_setting", "list_configuration_settings"], "a": "get_configuration_setting"}], "e": "DefaultAzureCredential uses the managed identity in Azure and your developer sign-in locally, with no code change. get_configuration_setting reads one key with a given label."},
{"id": "eh-114", "topic": "mon", "src": "imported", "num": 114, "type": "select", "q": "You are reviewing the Python tracing configuration for an application that must send distributed traces to Azure Monitor. The following code configures OpenTelemetry tracing:", "code": "01 from opentelemetry import trace\n02 from opentelemetry.sdk.trace import TracerProvider\n03 from opentelemetry.sdk.trace.export import BatchSpanProcessor\n04 from azure.monitor.opentelemetry.exporter import AzureMonitorTraceExporter\n06 trace.set_tracer_provider(TracerProvider())\n07 tracer = trace.get_tracer(__name__)\n09 exporter = AzureMonitorTraceExporter(connection_string=\"&lt;conn&gt;\")\n10 span_processor = BatchSpanProcessor(exporter)\n11 trace.get_tracer_provider().add_span_processor(span_processor)", "slots": [{"l": "The code configures the tracer provider before any spans are created.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "The configuration exports traces synchronously.", "c": ["Yes", "No"], "a": "No"}, {"l": "The configuration enables export to Azure Monitor.", "c": ["Yes", "No"], "a": "Yes"}], "e": "The provider is set first, BatchSpanProcessor exports in the background in batches (SimpleSpanProcessor would be synchronous), and the Azure Monitor exporter sends the spans to Application Insights."},
{"id": "eh-115", "topic": "mon", "src": "imported", "num": 115, "type": "select", "q": "A company uses Azure Monitor Application Insights to monitor application behavior, including incoming requests and dependencies. You must identify failed requests from the last hour. You must also calculate the average duration of failed request dependency calls, grouped by operation name. You need to analyze telemetry in Application Insights. Which operators should you use?", "code": "requests\n| [1] timestamp &gt; ago(1h) and success == false\n| join kind=inner (\n    dependencies\n    | [2] timestamp &gt; ago(1h)\n    | project operation_Id, depDuration = duration\n) on operation_Id\n| [3] avgDepDuration = avg(depDuration) by operation_Name", "slots": [{"l": "[1]", "c": ["extend", "project", "where"], "a": "where"}, {"l": "[2]", "c": ["distinct", "render", "where"], "a": "where"}, {"l": "[3]", "c": ["extend", "project", "summarize"], "a": "summarize"}], "e": "where filters rows by time and failure, join links each failed request to its dependency calls, and summarize computes the average duration per operation."},
{"id": "eh-116", "topic": "pg", "src": "imported", "num": 116, "type": "match", "q": "A Python API retrieves a document from Azure Database for PostgreSQL by using a SQL statement. The API accepts the document ID from user input. The current implementation inserts the document ID directly into the SQL statement. You need to secure the SQL statement execution by minimizing the possibility of SQL injection. How should you modify the current implementation?", "pairs": [["Modify the SQL statement structure.", "Use a parameterized query."], ["Bind user input.", "Pass the ID as an argument."], ["Execute the statement.", "Supply the parameter tuple to the SDK method."]], "extra": ["Escape quotation marks in the ID."], "e": "Use a placeholder (%s) in the SQL, pass the ID as a separate argument, and give the parameter tuple to cursor.execute. The driver handles quoting, so input can't change the statement. Escaping by hand isn't reliable."},
{"id": "eh-117", "topic": "sec", "src": "imported", "num": 117, "type": "order", "q": "You are deploying an Azure Function app that retrieves secrets from Key Vault by using a managed identity. The deployment must ensure that identity and secret configuration are in place before the function code is deployed. You need to deploy the function app securely. In which order should you perform the actions?", "items": ["Create the function app.", "Assign a managed identity to the function app.", "Grant the managed identity access to Key Vault.", "Add Key Vault references to application settings.", "Deploy the function code."], "e": "The app must exist before it can have an identity, the identity needs access before references can resolve, and everything must be in place before the code is deployed."},
{"id": "eh-118", "topic": "sec", "src": "imported", "num": 118, "type": "order", "q": "You are developing a serverless Java application on Azure. You create a new Azure Key Vault to work with secrets from a new Azure Functions application. The application must meet the following requirements: Reference the Azure Key Vault without requiring any changes to the Java code. Dynamically add and remove instances of the Azure Functions host based on the number of incoming application events. Ensure that instances are perpetually warm to avoid any cold starts. Connect to a VNet. Authentication to the Azure Key Vault instance must be removed if the Azure Functions application is deleted. You need to grant the Azure Functions application access to the Azure Key Vault. Which three actions should you perform in sequence?", "items": ["Create a user-assigned managed identity for the application.", "Create the Azure Functions app with a Premium plan type.", "Create an access policy in Azure Key Vault for the application identity."], "extra": ["Create the Azure Functions app with a Consumption plan type.", "Create an SSL certification in Azure Key Vault for the application identity.", "Create a system-assigned managed identity for the application.", "Create the Azure Functions app with an App Service plan type."], "e": "Premium gives event-driven scaling, always-warm instances and VNet integration, and a Key Vault access policy grants the identity access. The key uses a user-assigned identity, but only a system-assigned identity is deleted with the app, which is what the last requirement asks for; that version would create the app first, then the system-assigned identity, then the access policy."},
{"id": "eh-119", "topic": "mon", "src": "imported", "num": 119, "type": "match", "q": "A Python API running in ACA must send distributed traces to Azure Monitor. The API creates spans. However, no traces appear in Azure Monitor. You need to configure the OpenTelemetry SDK pipeline to export traces to Azure Monitor. What should you do?", "pairs": [["Register a global tracer provider.", "Initialize the application's TracerProvider for tracing."], ["Export traces to Azure Monitor.", "Create the Azure Monitor component that sends trace data."], ["Connect the exporter to the provider.", "Configure a span processor to send spans to the exporter."], ["Generate spans in the application code.", "Call tracer.start_as_current_span()."]], "extra": ["Enable log sampling."], "e": "Spans only reach Azure Monitor when the whole pipeline exists: a TracerProvider, an Azure Monitor exporter, and a span processor that connects them. The code then creates spans with start_as_current_span."},
{"id": "eh-120", "topic": "mon", "src": "imported", "num": 120, "type": "select", "q": "You are developing several microservices to run on Azure Container Apps. You need to monitor and diagnose the microservices. Which features should you use?", "slots": [{"l": "View console logs from a container in near real-time.", "c": ["Log streaming", "Container console", "Azure Monitor metrics", "Azure Monitor Log Analytics"], "a": "Log streaming"}, {"l": "Debug the microservice from inside the container.", "c": ["Container console", "Azure Monitor metrics", "Azure Container Registry", "Azure Monitor Log Analytics"], "a": "Container console"}], "e": "Log streaming shows container output live. The console opens a shell inside the running container for debugging."},
{"id": "eh-121", "topic": "aks", "src": "imported", "num": 121, "q": "An application deployed to AKS depends on an internal API hosted in the same cluster. All pods are healthy and report Ready status, but requests between the services time out. You need to determine whether the issue is related to Kubernetes service configuration or application code. What should you do first?", "o": ["Restart the failing deployment.", "Inspect Service and Endpoints objects.", "Increase replica count for both services.", "Test DNS resolution from your workstation."], "e": "If pods are Ready but calls time out, check the Service selector and its Endpoints first. An empty or wrong endpoint list means the Service isn't routing to the pods.", "a": 1},
{"id": "eh-122", "topic": "cosmos", "src": "imported", "num": 122, "q": "You are developing a Java application that uses Apache Cassandra to store key and value data. You plan to use a new Azure Cosmos DB resource and the Azure Cosmos DB for Apache Cassandra API in the application. You create a Microsoft Entra ID group named Azure Cosmos DB Creators to enable provisioning of Azure Cosmos DB accounts, databases, and containers. The Microsoft Entra ID group must not be able to access the keys that are required to access the data. You need to restrict access to the Microsoft Entra ID group. Which role-based access control should you use?", "o": ["Cosmos DB Operator", "Cosmos DB Account Reader", "Document DB Accounts Contributor", "Cosmos Backup Operator"], "e": "Cosmos DB Operator can provision accounts, databases and containers but can't read account keys or data.", "a": 0},
{"id": "eh-123", "topic": "mon", "src": "imported", "num": 123, "type": "order", "q": "You are investigating high latency in an AI search application that processes millions of requests daily. Telemetry is stored in Azure Monitor Logs. You must create a KQL query that correlates information from the AppRequests table and the AppDependencies table. The query must meet the following requirements: <br>• Include only data from the last 24 hours. <br>• Filter for failed requests only. <br>• Calculate the average duration of dependencies, grouped by operation. The query must be optimized for performance by minimizing the initial data scan. You need to create the query. Which five actions should you perform in sequence?", "items": ["Select the requests table.", "Apply a time filter.", "Filter the failed requests.", "Join the dependencies table.", "Summarize average dependency duration by operation."], "e": "Start from requests and filter by time first, then by failure, so the least data reaches the join. Join dependencies, then summarize the average duration per operation."},
{"id": "eh-124", "topic": "mon", "src": "imported", "num": 124, "q": "You are using Azure Monitor Application Insights to collect dependency data. You must be able to: <br>• Correlate failed requests with dependency calls during the last hour. <br>• Calculate the average dependency duration per operation. You need to construct the KOL query by using the minimum number of statements. Which three operators should you use?", "type": "multi", "o": ["extend", "summarize", "join", "where", "distinct"], "c": [1, 2, 3], "e": "where filters to the last hour and failed requests, join links requests to dependencies by operation, and summarize calculates the average duration per operation."},
{"id": "eh-125", "topic": "mon", "src": "imported", "num": 125, "q": "You are troubleshooting a production Azure OpenAI service that is experiencing intermittent connectivity issues. All telemetry is sent to a Log Analytics workspace. You must write a KQL query that analyzes the AppRequests table. The query must filter for requests that occurred within the last 30 minutes and have a failed status. The final output must display the total number of failures for each unique operation. You need to select the KQL operators required to filter the time range and aggregate the failure counts. Which two operators should you use?", "type": "multi", "o": ["summarize", "project", "distinct", "where"], "c": [0, 3], "e": "where filters by time and failed status, and summarize count() by operation produces the totals per operation."},
{"id": "eh-126", "topic": "sec", "src": "imported", "num": 126, "type": "match", "q": "You are configuring an Azure-hosted AI application that uses Azure App Configuration to manage its runtime settings. The application must provide the following functionality: <br>• Support percentage-based, targeted rollouts. <br>• Maximize token limits per request. <br>• Store a key that is retrieved securely at runtime. <br>• Reference a list of supported deployment regions. You need to configure the App Configuration features for the app. Which features should you configure?", "pairs": [["Support percentage-based, targeted rollouts.", "Feature flag"], ["Maximize token limits per request.", "Key-value"], ["Store a key that is retrieved securely at runtime.", "Key Vault reference"], ["Reference a list of supported deployment regions.", "Key-value"]], "extra": [], "e": "Feature flags support percentage and targeting filters. Ordinary settings such as a token limit or a region list are key-values, and secrets are stored as Key Vault references."},
{"id": "eh-127", "topic": "mon", "src": "imported", "num": 127, "type": "select", "q": "You are troubleshooting latency issues by using the requests table in Azure Monitor. You need to calculate the average request duration grouped by cloud role name and also limit results to the past 30 minutes. Which code elements should you select?", "code": "requests\n| [1] timestamp &gt; ago(30m)\n| [2] avg(duration) by cloud_RoleName", "slots": [{"l": "[1]", "c": ["distinct", "render", "where"], "a": "where"}, {"l": "[2]", "c": ["extend", "project", "summarize"], "a": "summarize"}], "e": "where limits the rows to the last 30 minutes, and summarize calculates the average per cloud role."},
{"id": "eh-128", "topic": "sec", "src": "imported", "num": 128, "q": "An AI application retrieves configuration values from App Configuration. The application uses static configuration. You need to implement a solution that supports dynamic configuration updates and minimizes latency for application requests. What should you do?", "o": ["Inject configuration values in environment variables.", "Cache configuration values with a refresh interval.", "Retrieve configuration values from App Configuration on each request.", "Store configuration values in Key Vault"], "e": "Caching values and refreshing them on an interval picks up changes without calling App Configuration on every request, which keeps latency low.", "a": 1},
{"id": "eh-129", "topic": "sec", "src": "imported", "num": 129, "q": "An AI application uses a database. The database credential rotates every 30 days. The application currently requires a manual update each time the credential rotates. You need to ensure that the application always uses the latest secret version without manual updates. Which two actions should you perform?", "type": "multi", "o": ["Retrieve secrets without specifying a version identifier.", "Retrieve secrets by specifying a version identifier.", "Cache the secret for 30 days.", "Configure a Key Vault rotation policy."], "c": [0, 3], "e": "A rotation policy rotates the secret automatically, and reading it without a version always returns the current value."},
{"id": "eh-130", "topic": "sec", "src": "imported", "num": 130, "type": "select", "q": "You are developing an AI application that retrieves database credentials from Key Vault by using the Azure SDK for Python. The application must use managed identity for authentication. You review the following code segment that retrieves a secret from Key Vault.", "code": "01 from azure.identity import DefaultAzureCredential\n02 from azure.keyvault.secrets import SecretClient\n04 credential = DefaultAzureCredential()\n05 client = SecretClient(\n06     vault_url=\"https://vault.vault.azure.net/\",\n07     credential=credential\n08 )\n10 secret = client.get_secret(\"dbPassword\", version=\"123\")", "slots": [{"l": "The code retrieves the latest version of dbPassword.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "The code authenticates to Key Vault without storing client secrets in the application when deployed to an Azure-hosted environment that has a managed identity enabled.", "c": ["Yes", "No"], "a": "Yes"}, {"l": "If dbPassword is rotated and a new version is created, subsequent calls to this code will retrieve the new version.", "c": ["Yes", "No"], "a": "Yes"}], "e": "DefaultAzureCredential uses the managed identity in Azure, so no secret is stored. The key says Yes to all three, but line 10 pins version=\"123\", so the code always reads that version; the first and third statements look like No."},
{"id": "eh-131", "topic": "mon", "src": "imported", "num": 131, "type": "match", "q": "You are configuring sampling for a distributed application that sends traces to Azure Monitor. The solution must - <br>• Preserve upstream sampling decisions across distributed traces. <br>• Capture all spans during local testing. <br>• Sample 10 percent of traces in production. You need to apply the appropriate sampling configuration for each requirement. What should you do?", "pairs": [["Maintain parent sampling decisions.", "ParentBasedSampler"], ["Record all spans during testing.", "AlwaysOnSampler"], ["Sample 10 percent of traces in production.", "TraceIdRatioBasedSampler(0.1)"]], "extra": ["BatchSpanProcessor", "AzureMonitorTraceExporter"], "e": "ParentBasedSampler follows the upstream decision, AlwaysOnSampler records everything, and TraceIdRatioBasedSampler(0.1) keeps 10% of traces. The processor and exporter aren't samplers."},
{"id": "eh-132", "topic": "sec", "src": "imported", "num": 132, "type": "match", "q": "You are reviewing secret access patterns used by an AI application that retrieves credentials from Key Vault. You need to evaluate the security impact of each implementation approach. What is the outcome of each approach?", "pairs": [["Retrieve secret without specifying version.", "Supports automatic rotation"], ["Retrieve secret with version identifier.", "Requires manual update after rotation"], ["Use managed identity for authentication.", "Prevents credential storage"], ["Use client secret stored in environment variables.", "Introduces credential exposure"]], "extra": [], "e": "Unversioned reads always get the current value, pinned versions need a code or config change after rotation, managed identities remove stored credentials, and a client secret in the environment is a credential that can leak."},
{"id": "eh-133", "topic": "mon", "src": "imported", "num": 133, "q": "You are using Azure Monitor Application Insights to investigate a production API. You open the Logs blade and set the time range to Last 24 hours. An engineer recommends the following query to count requests by result code and sort the results from most frequent to least frequent: requests | summarize request_count = count() by resultCode | order by request_count desc You need to determine whether the query returns the number of requests grouped by result code and sorted from most to least frequent. Solution: The query lists every individual request along with its result code. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "summarize groups the rows, so the query returns one row per result code, not one per request.", "a": 1, "fixed": true},
{"id": "eh-134", "topic": "mon", "src": "imported", "num": 134, "q": "You are using Azure Monitor Application Insights to investigate a production API. You open the Logs blade and set the time range to Last 24 hours. An engineer recommends the following query to count requests by result code and sort the results from most frequent to least frequent: requests | summarize request_count = count() by resultCode | order by request_count desc You need to determine whether the query returns the number of requests grouped by result code and sorted from most to least frequent. Solution: The result codes are sorted alphabetically. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "order by request_count desc sorts by the count, from highest to lowest, not alphabetically by result code.", "a": 1, "fixed": true},
{"id": "eh-135", "topic": "mon", "src": "imported", "num": 135, "q": "You are using Azure Monitor Application Insights to investigate a production API. You open the Logs blade and set the time range to Last 24 hours. An engineer recommends the following query to count requests by result code and sort the results from most frequent to least frequent: requests | summarize request_count = count() by resultCode | order by request_count desc You need to determine whether the query returns the number of requests grouped by result code and sorted from most to least frequent. Solution: The query returns one row per unique resultCode value with the number of requests in each group. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "summarize count() by resultCode gives one row per result code with its count, and order by ... desc puts the most frequent first.", "a": 0, "fixed": true},
{"id": "eh-136", "topic": "sec", "src": "imported", "num": 136, "q": "You plan to deploy a container to an Azure App Service API app named api1. You host the source code for api1 in a GitHub repository. The container uses the API key at runtime to connect to a backend service. The container must be able to retrieve the API key at runtime without exposing it in the source repository or Git commit history. You need to ensure that the API key remains outside of Git commit history and is available to the container at runtime. Solution: Store the API key as an App Service application setting configured through the Azure Portal. Does the solution meet the goal?", "o": ["Yes", "No"], "e": "The answer key says No. A plain app setting does keep the key out of Git and available at runtime; the intended answer for this series is a Key Vault reference, which also stores the secret securely.", "a": 1, "fixed": true},
{"id": "eh-137", "topic": "mon", "src": "imported", "num": 137, "case": "proseware", "q": "You need to perform a one-time analysis of logs collected from AKS, ACA, and Azure Function apps according to the business requirements. What should you use?", "o": ["KQL query", "Azure activity log", "Python function", "Azure Monitor workbook"], "e": "All three services send logs to the same Log Analytics workspace, so a single KQL query is the quickest one-time analysis.", "a": 0},
{"id": "eh-138", "topic": "sec", "src": "imported", "num": 138, "case": "proseware", "q": "You need to configure a connection string for the partner-facing service according to the technical requirements. What should you use?", "o": ["GitHub secrets", "Dockerfile ENV instructions", "Azure Container Registry Helm chart package", "App Service environment variables"], "e": "App Service must supply secrets at runtime without relying on an external service, which App Service environment variables (app settings) do. The other options put secrets in the build or the image.", "a": 3},
{"id": "eh-139", "topic": "aca", "src": "imported", "num": 139, "q": "You are developing a microservices-based application that uses Azure Container Apps. The application consists of several containerized services that handle tasks, such as processing orders, managing inventory, and generating reports. You deploy a new revision of the processing orders app. Processing orders must be triggered by a web request and must always be available based on incoming web requests. You need to validate that the replica is ready to handle incoming requests. What should you implement?", "o": ["HTTP liveness probe", "HTTP startup probe", "TCP readiness probe", "HTTP readiness probe", "TCP liveness probe"], "e": "A readiness probe decides whether a replica receives traffic. The app is triggered by web requests, so an HTTP readiness probe checks it can actually serve them.", "a": 3},
{"id": "eh-140", "topic": "sec", "src": "imported", "num": 140, "q": "You develop an ASP.NET Core app that uses Azure App Configuration. You also create an App Configuration containing 100 settings. The app must meet the following requirements: <br>• Ensure the consistency of all configuration data when changes to individual settings occur. <br>• Handle configuration data changes dynamically without causing the application to restart. <br>• Reduce the overall number of requests made to App Configuration APIs. You must implement dynamic configuration updates in the app. What are two ways to achieve this goal?", "type": "multi", "o": ["Create and configure Azure Key Vault. Implement the Azure Key Vault configuration provider.", "Register all keys in the App Configuration store. Set the refreshAll parameter of the Register method to false.", "Create and register a sentinel key in the App Configuration store. Set the refreshAll parameter of the Register method to true.", "Decrease the App Configuration cache expiration from the default value.", "Increase the App Configuration cache expiration from the default value.", "Create and implement environment variables for each App Configuration store setting."], "c": [2, 4], "e": "Register a sentinel key with refreshAll set to true, so all settings reload together when it changes. Increasing the cache expiration reduces the number of requests to App Configuration."},
{"id": "eh-n20", "topic": "aca", "src": "imported", "num": 141, "type": "order", "q": "You create an Azure subscription. You then create an Azure resource group. You plan to create a containerized task that will run as an Azure Container App in regular intervals. You need to automate the process of creating the task in the resource group by using Azure CLI commands. Which three commands should you arrange in sequence to develop the solution?", "items": ["az provider register --namespace Microsoft.App", "az containerapp env create", "az containerapp job create --trigger-type Schedule --cron-expression \"...\""], "extra": ["az containerapp create", "az group create", "az containerapp job start"], "e": "A new subscription must first register the Microsoft.App resource provider. A task that runs on a schedule is a Container Apps job, and every job needs a Container Apps environment, so you create the environment and then the job with a Schedule trigger and a cron expression. az containerapp create makes an always-running app, the resource group already exists, and a scheduled job starts on its own. (This answer is my own: the PDF shows its answer as an image, which wasn't in the text copy you sent.)"},
{"id": "eh-n57", "topic": "cosmos", "src": "imported", "num": 142, "type": "multi", "q": "You are developing a solution that will use a multi-partitioned Azure Cosmos DB database. You plan to use the latest Azure Cosmos DB SDK for development. The solution must meet the following requirements:<br>• Send insert and update operations to an Azure Blob storage account.<br>• Process changes to all partitions immediately.<br>• Allow parallelization of change processing.<br>You need to process the Azure Cosmos DB operations. What are two possible ways to achieve this goal?", "o": ["Create an Azure Function to use a trigger for Azure Cosmos DB. Configure the trigger to connect to the container.", "Create an Azure App Service API and implement the change feed estimator of the SDK. Scale the API by using multiple Azure App Service instances.", "Create a background job in an Azure Kubernetes Service and implement the change feed feature of the SDK.", "Create an Azure Function that uses a FeedIterator object that processes the change feed by using the pull model on the container. Use a FeedRange object to parallelize the processing of the change feed across multiple functions."], "c": [0, 3], "e": "The Azure Cosmos DB trigger for Functions reads the change feed for every partition as changes arrive and scales out automatically. The pull model with FeedIterator, split by FeedRange, lets several functions process different parts of the change feed in parallel. The change feed estimator only measures how far behind processing is; it doesn't process changes."},
{"id": "eh-n58", "topic": "cosmos", "src": "imported", "num": 143, "type": "select", "q": "A company has an Azure Cosmos DB for NoSQL account. The account is configured for session consistency. Data is written to a single Azure region and data can be read from three Azure regions. An application that will access the Azure Cosmos DB for NoSQL container data using an SDK has the following requirements:<br>• Reads from the application must return the most recent committed version of an item from any Azure region.<br>• The container items should not automatically be deleted.<br>You need to implement the changes to the Azure Cosmos DB for NoSQL account. What should you do?", "slots": [{"l": "Default consistency level", "c": ["Strong", "Bounded staleness", "Session", "Consistent prefix", "Eventual"], "a": "Strong"}, {"l": "Time to Live on the container", "c": ["Off", "On (no default)", "On (default 3600 seconds)"], "a": "Off"}], "e": "Only Strong consistency guarantees every region returns the latest committed write, and the PDF's answer text confirms Strong for the first box. Turning Time to Live off means items never expire automatically. The second box and its options are my own, because the PDF's answer area is an image that wasn't in the text copy you sent."},
{"id": "eh-n59", "topic": "cosmos", "src": "imported", "num": 144, "q": "You manage an Azure Cosmos DB for a NoSQL API account named account1. The account contains a database named db1, which contains a container named container1. You configure account1 with a session consistency level. You plan to develop an application named App1 that will access container1. Individual instances of App1 must perform reads and writes. App1 must allow multiple nodes to participate in the same session. You need to configure an object to share the session token between the nodes. Which object should you use?", "o": ["Document response", "Connection policy", "Feed options", "Request options"], "a": 0, "e": "The session token comes back on the response of each write (the document response), so that is where a node gets the token to share. The answer key says Document response. Note that the token is then passed to the other nodes through request options (for example ItemRequestOptions.SessionToken), so some sources give Request options as the answer."},
{"id": "eh-n96", "topic": "events", "src": "imported", "num": 145, "type": "order", "q": "You develop software solutions for a mobile delivery service. You are developing a mobile app that users can use to order from a restaurant in their area. The app uses the following workflow:<br>1. A driver selects the restaurants for which they will deliver orders.<br>2. Orders are sent to all available drivers in an area.<br>3. Only orders for the selected restaurants will appear for the driver.<br>4. The first driver to accept an order removes it from the list of available orders.<br>You need to implement an Azure Service Bus solution. Which three actions should you perform in sequence?", "items": ["Create a Service Bus topic with a subscription for each restaurant.", "Configure a SQL filter on each subscription to filter for specific restaurant IDs.", "Use Peek-Lock mode to receive messages from the subscriptions."], "extra": ["Create a Service Bus queue for each driver.", "Use Receive and Delete mode to receive messages from the subscriptions."], "e": "A topic lets one order reach many subscribers, a SQL filter on each subscription limits it to the chosen restaurants, and Peek-Lock lets the first driver to complete the message take the order. The two unused actions are my own distractors, because the PDF's action list is an image that wasn't in the text file."},
{"id": "eh-n146", "topic": "sec", "src": "imported", "num": 146, "type": "select", "q": "You are a developer building a web site using a web app. The web site stores configuration data in Azure App Configuration. Access to Azure App Configuration has been configured to use the identity of the web app for authentication. Security requirements specify that no other authentication systems must be used. You import all required libraries. You need to load configuration data from Azure App Configuration. How should you complete the code?", "code": "var builder = WebApplication.CreateBuilder(args);\nbuilder.Configuration.[1](options =&gt;\n{\n    options.Connect(\n        new Uri(builder.Configuration[\"AppConfig:Endpoint\"]),\n        new [2]());\n});", "slots": [{"l": "[1]", "c": ["AddAzureAppConfiguration", "AddAzureKeyVault", "AddEnvironmentVariables"], "a": "AddAzureAppConfiguration"}, {"l": "[2]", "c": ["ManagedIdentityCredential", "DefaultAzureCredential", "ClientSecretCredential", "InteractiveBrowserCredential"], "a": "ManagedIdentityCredential"}], "e": "AddAzureAppConfiguration loads settings from the store, connecting with its endpoint rather than a connection string. ManagedIdentityCredential uses only the web app's identity. DefaultAzureCredential would also try other sign-in methods, which the security requirement rules out. (The PDF shows this code as an image, which wasn't in the text copy you sent, so I wrote this version of the code and its options myself.)"},
{"id": "eh-n147", "topic": "sec", "src": "imported", "num": 147, "type": "match", "q": "A company has an Azure subscription named Sub1. Sub1 contains an App Configuration store named AppConfig1. You plan to implement an App Service web app named App1, which will be accessed by users in your organization. App1 will have a dev, test, and prod instance. Each web app instance will connect to a different back-end API endpoint. For each web app instance, you plan to assign a different layout of webpages to different groups of users based on their department. The implementation must ensure that:<br>• API endpoint details are stored in the JSON format and encrypted with a custom key.<br>• User assignments of layout pages can be changed without any web app code modifications.<br>You need to configure AppConfig1 to support your implementation. What should you create in AppConfig1?", "pairs": [["API endpoint details (JSON, encrypted with a custom key)", "Key Vault reference"], ["User assignments of layout pages (changed without code modifications)", "Feature flag"]], "extra": ["Key-value", "Label"], "e": "A Key Vault reference keeps the endpoint details in Key Vault, where they can be encrypted with your own key. A feature flag with a targeting filter assigns layouts to groups of users, and you change it in App Configuration without touching code. Key-value and Label are my own distractors, because the PDF's option list is an image."}
];
